function normalizeState(target){target.transactions=Array.isArray(target.transactions)?target.transactions:[];target.reviewQueue=Array.isArray(target.reviewQueue)?target.reviewQueue:[];target.goals=(Array.isArray(target.goals)?target.goals:[]).map(g=>({...g,editLimit:Number(g.editLimit)||MAX_GOAL_EDITS,editsUsed:Math.max(0,Number(g.editsUsed)||0)}));return target}
function importedReviewType(tx){if(tx.category==="Savings"||tx.category==="Transfers")return"transfer";return tx.type}
function importedReviewCategory(tx){return tx.category==="Transfers"?"Transfer Review":tx.category}
function importedReviewNote(tx){if(tx.category==="Savings")return"Statement import. Confirm if this is Spend & Save, CashBox, SmartEarn, Piggyvest, or another protected savings movement before it affects reports.";if(tx.category==="Transfers")return"Statement import. Confirm if this was POS cash, family loan, internal transfer, pass-through money, or actual spending.";return`Statement import from ${tx.account}. Confirm the category before FinMax treats this as ledger truth.`}
function seedImportedTransactionsForReview(){const privateRows=globalThis.FINMAX_PRIVATE_REVIEW_DATA?.rows;if(Array.isArray(privateRows)&&privateRows.length){seed.reviewQueue=privateRows;seed.transactions=[];normalizeState(seed);return}const imported=(seed.transactions||[]).map(tx=>({id:`import_${tx.id}`,date:tx.date,name:tx.name,suggestedCategory:importedReviewCategory(tx),suggestedType:importedReviewType(tx),accountId:tx.accountId,amount:tx.amount,note:importedReviewNote(tx),source:"seeded-statement-review",sourceTransactionId:tx.id}));seed.reviewQueue=[...imported,...(seed.reviewQueue||[])];seed.transactions=[];normalizeState(seed)}

