function loadUserDb(){try{const parsed=JSON.parse(localStorage.getItem(USER_DB_KEY)||'{"users":[]}');return{users:Array.isArray(parsed.users)?parsed.users:[]}}catch{return{users:[]}}}
function saveUserDb(){localStorage.setItem(USER_DB_KEY,JSON.stringify(db))}
function load(){try{return merge(structuredClone(seed),JSON.parse(localStorage.getItem(KEY)||"{}"))}catch{return structuredClone(seed)}}
function merge(base,patch){return{...base,...patch,profile:{...base.profile,...(patch.profile||{})},accounts:Array.isArray(patch.accounts)?patch.accounts:base.accounts,transactions:Array.isArray(patch.transactions)?patch.transactions:base.transactions,reviewQueue:Array.isArray(patch.reviewQueue)?patch.reviewQueue:base.reviewQueue,assets:Array.isArray(patch.assets)?patch.assets:base.assets,liabilities:Array.isArray(patch.liabilities)?patch.liabilities:base.liabilities,loans:Array.isArray(patch.loans)?patch.loans:base.loans,loansGiven:Array.isArray(patch.loansGiven)?patch.loansGiven:base.loansGiven,subscriptions:Array.isArray(patch.subscriptions)?patch.subscriptions:base.subscriptions,goals:Array.isArray(patch.goals)?patch.goals:base.goals,incomePaths:Array.isArray(patch.incomePaths)?patch.incomePaths:base.incomePaths,monthly:Array.isArray(patch.monthly)?patch.monthly:base.monthly}}
function currentNav(){return state.profile.mode==="executive"?executiveNav:state.profile.mode==="rank"?rankNav:everydayNav}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function uid(prefix){return `${prefix}_${Date.now()}_${Math.random().toString(16).slice(2)}`}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]))}
function theme(){if(state.profile.theme!=="system")return state.profile.theme;return matchMedia("(prefers-color-scheme:dark)").matches?"dark":"light"}
function money(value,compact=false){const opts={style:"currency",currency:state.profile.currency,maximumFractionDigits:compact?0:2,notation:compact?"compact":"standard"};return new Intl.NumberFormat(undefined,opts).format(value)}
function moneyIn(value,currency=state.profile.currency,compact=false){const opts={style:"currency",currency,maximumFractionDigits:compact?0:2,notation:compact?"compact":"standard"};return new Intl.NumberFormat(undefined,opts).format(Number(value)||0)}
function convertMoney(value,from,to){if(from===to)return Number(value)||0;const rate=Math.max(1,Number(state.profile.fxUsdNgn)||1);if(from==="USD"&&to==="NGN")return Number(value)*rate;if(from==="NGN"&&to==="USD")return Number(value)/rate;return Number(value)||0}
function signed(value){return `${value>=0?"+":"-"}${money(Math.abs(value))}`}
function sum(items,key="value"){return items.reduce((n,x)=>n+Number(x[key]||0),0)}
function isProtectedMovement(tx){return tx.category==="Savings"||/save|savings|cashbox|smartearn|spend & save|piggyvest/i.test(`${tx.name} ${tx.account}`)}
function reviewTypeToLedger(type){return type==="loan-given"?"expense":type==="loan-received"?"income":type==="transfer"?"transfer":type}
function modeLabel(){return({everyday:"Everyday view",executive:"Executive view",rank:"Rank mode"}[state.profile.mode]||"Everyday view")}
function passwordRules(value,confirm=""){return[{key:"length",label:"8+ characters",ok:value.length>=8},{key:"letter",label:"Has a letter",ok:/[a-z]/i.test(value)},{key:"number",label:"Has a number",ok:/\d/.test(value)},{key:"symbol",label:"Has a symbol",ok:/[^A-Za-z0-9]/.test(value)},{key:"match",label:"Passwords match",ok:Boolean(value)&&value===confirm}]}
function passwordRulesMarkup(value="",confirm=""){return `<div class="password-rules" data-password-rules>${passwordRules(value,confirm).map(rule=>`<span data-rule="${rule.key}" class="${rule.ok?"ok":""}">${rule.ok?"✓":"•"} ${rule.label}</span>`).join("")}</div>`}
function movementTotals(){const income=sum(state.transactions.filter(x=>x.type==="income"),"amount"),grossOutflow=sum(state.transactions.filter(x=>x.type==="expense"),"amount"),protectedSavings=sum(state.transactions.filter(x=>x.type==="expense"&&isProtectedMovement(x)),"amount"),reviewCount=(state.reviewQueue||[]).length,spending=Math.max(0,grossOutflow-protectedSavings),netOperating=income-spending;return{income,grossOutflow,protectedSavings,spending,netOperating,reviewCount}}
function totals(){const m=movementTotals(),assets=sum(state.assets)+sum(state.accounts,"balance"),liabilities=sum(state.liabilities);return{income:m.income,expense:m.spending,grossOutflow:m.grossOutflow,protectedSavings:m.protectedSavings,cashflow:m.netOperating,assets,liabilities,netWorth:assets-liabilities}}
function route(next){view=next;modal=null;render();scrollTo({top:0,behavior:"smooth"})}

function render(){document.body.dataset.theme=theme();document.body.dataset.accent=state.profile.accent;document.documentElement.style.setProperty("--density",state.profile.density);app.innerHTML=!state.profile.onboarded?onboarding():!authenticated?authScreen():shell();}
function shell(){return `<div class="app">${sidebar()}<main class="main">${topbar()}<section class="content">${page()}</section>${mobileNav()}</main>${modal?modalView():""}${!state.profile.tutorialDone?tutorial():""}</div>`}
function sidebar(){return `<aside class="sidebar"><div class="brand"><span class="brand-mark">F</span><div>FinMax <small>Private Finance OS</small></div></div><nav class="nav">${currentNav().map(n=>navButton(...n)).join("")}</nav><div class="sidebar-foot"><button class="btn privacy-toggle" data-action="privacy">${state.profile.privacy?"Show values":"Hide values"}</button><div class="profile-mini"><span class="avatar" aria-hidden="true">$</span><div><strong>${esc(state.profile.name)}</strong><small>${modeLabel()}</small></div></div></div></aside>`}
function navButton(id,icon,label){return `<button class="nav-btn ${view===id?"active":""}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`}
function mobileNav(){const items=currentNav();return `<nav class="mobile-nav" style="grid-template-columns:repeat(${items.length},minmax(68px,1fr))">${items.map(([id,icon,label])=>`<button class="${view===id?"active":""}" data-view="${id}"><span>${icon}</span>${label.replace("Transactions","Activity").replace("Subscriptions","Subs").replace("Customize","Settings")}</button>`).join("")}</nav>`}
function topbar(){const names={dashboard:state.profile.mode==="everyday"?"Today":state.profile.mode==="rank"?"Rank Command":"Overview",review:"Transaction Review",accounts:"Accounts",transactions:"Transactions",goals:"Goals",advisor:"FinMax Advisor",wealth:"Net Worth",loans:"Loans",subscriptions:"Subscriptions",analytics:"Analytics",settings:"Customize"};return `<header class="topbar"><h1>${names[view]}</h1><div class="top-actions"><div class="segmented"><button class="${state.profile.mode==="everyday"?"active":""}" data-mode="everyday">Everyday</button><button class="${state.profile.mode==="executive"?"active":""}" data-mode="executive">Executive</button><button class="${state.profile.mode==="rank"?"active":""}" data-mode="rank">Rank</button></div><button class="btn icon" data-action="privacy" title="Hide balances">${state.profile.privacy?"◉":"◌"}</button><button class="btn primary" data-open="transaction">+ Add</button></div></header>`}
function page(){return({dashboard,review,accounts,transactions,goals,advisor,wealth,loans,subscriptions,analytics,settings}[view]||dashboard)()}

function onboarding(){return `<section class="onboarding"><div class="onboard-art"><div class="brand"><span class="brand-mark">F</span>FinMax</div><div><h1>Know what your money can do next.</h1><p>A private financial operating system for daily clarity, long-term wealth, and every decision in between.</p></div><small>Your data stays on this device.</small></div><div class="onboard-panel"><div class="eyebrow">Private by default</div><h2>Build your financial cockpit</h2><p class="muted">Three choices. No bank connection required.</p><form class="grid" data-form="onboard"><div class="field"><label>Your name</label><input name="name" required placeholder="What should we call you?"></div><div class="field"><label>Primary currency</label><select name="currency"><option>NGN</option><option>USD</option><option>GBP</option><option>EUR</option><option>CAD</option></select></div><div class="field"><label>Starting view</label><div class="choice-grid triple"><button class="choice active" type="button" data-choice="everyday"><strong>Everyday</strong><br><small>Simple cashflow and obligations</small></button><button class="choice" type="button" data-choice="executive"><strong>Executive</strong><br><small>Full wealth and leverage context</small></button><button class="choice" type="button" data-choice="rank"><strong>Rank</strong><br><small>XP, review queue, and recovery mode</small></button></div><input name="mode" value="everyday" hidden></div><button class="btn primary" style="min-height:50px">Continue to account</button></form></div></section>`}
function authScreen(){return authLayout(authMode==="signup"?"Create your FinMax account":"Welcome back",authMode==="signup"?"This offline build stores a real local account database in this browser. Passwords are hashed before they are stored.":"Sign in with a saved local account to unlock this device.",`${authTabs()}${authMode==="signup"?signupForm():loginForm()}<p class="muted auth-hint"><strong>Local account database:</strong> ${db.users.length} saved ${db.users.length===1?"user":"users"} on this browser.</p>`)}
function authTabs(){return `<div class="auth-tabs"><button class="${authMode==="signup"?"active":""}" type="button" data-auth-mode="signup">Sign Up</button><button class="${authMode==="login"?"active":""}" type="button" data-auth-mode="login">Login</button></div>`}
function signupForm(){return `<form class="grid" data-form="signup"><div class="field"><label>Display name</label><input name="displayName" required autocomplete="name" value="${esc(state.profile.name)}"></div><div class="field"><label>Username</label><input name="username" required autocomplete="username" placeholder="Choose a username"></div><div class="field"><label>Password</label><div class="password-field"><input name="password" type="password" minlength="8" required autocomplete="new-password" placeholder="8+ characters, letter, number, symbol" data-password-watch><button type="button" data-toggle-password>Show</button></div></div><div class="field"><label>Confirm password</label><div class="password-field"><input name="confirm" type="password" minlength="8" required autocomplete="new-password" data-password-watch><button type="button" data-toggle-password>Show</button></div></div>${passwordRulesMarkup()}<button class="btn primary" style="min-height:50px">Create Account</button></form>`}
function loginForm(){return `<form class="grid" data-form="login"><div class="field"><label>Username</label><input name="username" required autocomplete="username" value="${esc(db.users[0]?.username||state.profile.username)}"></div><div class="field"><label>Password</label><div class="password-field"><input name="password" type="password" required autocomplete="current-password"><button type="button" data-toggle-password>Show</button></div></div><button class="btn primary" style="min-height:50px">Login</button></form>`}
function authLayout(title,copy,form){return `<section class="onboarding"><div class="onboard-art"><div class="brand"><span class="brand-mark">F</span>FinMax</div><div><h1>Your finances.<br>Your device.<br>Your control.</h1><p>No cloud account is required for this offline submission.</p></div><small>Local SHA-256 credential verification</small></div><div class="onboard-panel"><div class="eyebrow">Offline access</div><h2>${title}</h2><p class="muted">${copy}</p>${form}</div></section>`}
async function hashPassword(value){const input=`finmax::${value}`;if(globalThis.crypto?.subtle){const bytes=new TextEncoder().encode(input),hash=await crypto.subtle.digest("SHA-256",bytes);return Array.from(new Uint8Array(hash)).map(x=>x.toString(16).padStart(2,"0")).join("")}let h=2166136261;for(let i=0;i<input.length;i++){h^=input.charCodeAt(i);h=Math.imul(h,16777619)}return `local-${(h>>>0).toString(16).padStart(8,"0")}`}

function dashboard(){return state.profile.mode==="executive"?executiveDashboard():state.profile.mode==="rank"?rankDashboard():everydayDashboard()}
function executiveDashboard(){const t=totals(),available=sum(state.accounts,"balance"),saveRate=t.income?Math.round(t.cashflow/t.income*100):0;return `${pageHead(`Good ${greeting()}, ${esc(state.profile.name)}`,"Your capital, obligations, and opportunities in one view.",`<button class="btn" data-open="transaction">Add transaction</button>`)}<div class="grid kpi-grid">${kpi("Net worth",t.netWorth,"Across all assets","positive")}${kpi("Available across accounts",available,`${state.accounts.length} connected offline ledgers`)}${kpi("Net cashflow",t.cashflow,`${saveRate}% savings rate`,t.cashflow>=0?"positive":"negative")}${kpi("Monthly commitments",monthlyCommitments(),`${state.subscriptions.filter(x=>x.active).length} subscriptions + debt`)}</div><div class="grid dash-grid"><div class="grid"><article class="card card-pad"><div class="card-head"><div><h3>Cashflow trajectory</h3><span class="muted">Income against spending</span></div><span class="badge active">6 months</span></div>${cashflowChart()}</article><article class="card card-pad"><div class="card-head"><h3>Recent activity</h3><button class="btn small" data-view="transactions">View all</button></div><div class="activity">${state.transactions.slice(0,5).map(txRow).join("")}</div></article></div><aside class="grid"><article class="card card-pad"><div class="card-head"><h3>Account snapshot</h3><button class="btn small" data-view="accounts">Manage</button></div>${state.accounts.slice(0,4).map(accountMini).join("")}</article><article class="card card-pad"><div class="card-head"><h3>Spending map</h3><span class="muted">This period</span></div>${categoryRows()}</article><article class="card card-pad"><div class="card-head"><h3>Financial signal</h3><span class="badge active">Healthy</span></div><div class="insight"><strong>You are retaining ${saveRate}% of recorded income.</strong><p class="muted">Your accounts currently hold ${money(available)} across personal, business, and cash ledgers.</p></div></article><article class="card card-pad"><h3>Capital efficiency</h3><div class="kpi-value">${Math.round(t.assets/(t.liabilities||1)*100)/100}×</div><span class="muted">Assets per unit of liability</span></article></aside></div>`}
function everydayDashboard(){const t=totals(),available=sum(state.accounts,"balance"),commitments=monthlyCommitments(),reserveGap=Math.max(0,state.profile.reserveTarget-available),safe=Math.max(0,available-commitments-Math.max(0,reserveGap*.25)),spent=t.expense,budget=state.profile.monthlyBudget,pace=Math.round(spent/budget*100),goal=[...state.goals].sort((a,b)=>a.priority-b.priority)[0],advice=advisorData()[0];return `${pageHead(`Good ${greeting()}, ${esc(state.profile.name)}`,"Here is what matters most for your money today.",`<button class="btn primary" data-open="transaction">Log activity</button>`)}<article class="card safe-card"><div><span class="eyebrow">Safe to spend</span><div class="safe-value privacy-amount" data-hidden="${state.profile.privacy}">${money(safe)}</div><p>After planned commitments and reserve protection.</p></div><div class="safe-score"><strong>${Math.max(0,100-pace)}</strong><span>flexibility</span></div></article><div class="grid everyday-grid"><div class="grid"><article class="card card-pad"><div class="card-head"><div><h3>Spending pace</h3><span class="muted">${money(spent)} of ${money(budget)} monthly guardrail</span></div><strong class="${pace>85?"negative":"positive"}">${pace}%</strong></div><div class="progress pace"><span style="--value:${Math.min(100,pace)}%"></span></div><p class="muted">${pace>100?`You are ${money(spent-budget)} above your current guardrail.`:pace>80?"Slow discretionary spending to avoid crossing your limit.":`You have ${money(Math.max(0,budget-spent))} left within your current guardrail.`}</p></article><article class="card card-pad"><div class="card-head"><div><h3>Active goal</h3><span class="muted">${esc(goal?.name||"Create your first goal")}</span></div><button class="btn small" data-view="goals">Open goals</button></div>${goal?goalProgress(goal):""}</article><article class="card card-pad"><div class="card-head"><h3>Recent activity</h3><button class="btn small" data-view="transactions">View all</button></div>${state.transactions.slice(0,4).map(txRow).join("")}</article></div><aside class="grid"><article class="card advisor-preview"><span class="eyebrow">Next best move</span><h2>${advice.title}</h2><p>${advice.text}</p><button class="btn primary" data-view="advisor">See my action plan</button></article><article class="card card-pad"><div class="card-head"><h3>Coming up</h3><span class="badge">Next cycle</span></div>${upcomingRows(4)}</article><article class="card card-pad"><h3>Reserve protection</h3><div class="kpi-value">${reserveGap?money(reserveGap,true):"Ready"}</div><span class="muted">${reserveGap?"remaining to your preferred reserve":"reserve target reached"}</span></article></aside></div>`}
function rankDashboard(){const t=totals(),m=movementTotals(),goal=activeGoal(),xp=Math.max(0,Math.round((m.income*.012)+(m.protectedSavings*.018)+(state.transactions.length*9)-(m.spending*.004)-(m.reviewCount*35))),rank=xp>8000?"A":xp>5000?"B":xp>2500?"C":xp>1000?"D":"E",next={E:1000,D:2500,C:5000,B:8000,A:12000}[rank]||12000,pct=Math.min(100,Math.round(xp/next*100)),savingRate=m.income?Math.round(m.protectedSavings/m.income*100):0;return `${pageHead(`Rank Mode, ${esc(state.profile.name)}`,"A sharper command view: review imports, protect savings, and convert money motion into progress.",`<button class="btn primary" data-view="review">Open review queue</button>`)}<section class="rank-hero card"><div><span class="eyebrow">Financial Rank</span><h2>${rank} Rank</h2><p>${m.reviewCount?`${m.reviewCount} imported items need judgement before FinMax treats them as truth.`:"Your transaction queue is clear. Keep logging and protecting savings."}</p></div><div class="rank-orb"><strong>${rank}</strong><span>${xp} XP</span></div></section><div class="grid kpi-grid rank-kpis">${kpi("Reviewed logs",state.transactions.length,"approved ledger entries","positive")}${kpi("Pending review",m.reviewCount,"needs classification",m.reviewCount?"negative":"positive")}${kpi("Protected savings",m.protectedSavings,"not counted as spending","positive")}${kpi("Saving shield",`${savingRate}%`,"protected out of income",savingRate>=20?"positive":"")}</div><div class="grid dash-grid"><article class="card card-pad"><div class="card-head"><div><h3>Rank progress</h3><span class="muted">${xp} / ${next} XP toward the next bracket</span></div><span class="badge active">Recovery Mode</span></div><div class="rank-track"><span style="--value:${pct}%"></span></div><div class="rank-missions"><button class="btn" data-view="review">Classify imports</button><button class="btn" data-open="transaction">Log new activity</button><button class="btn primary" data-view="goals">Push main goal</button></div></article><aside class="grid"><article class="card card-pad"><div class="card-head"><h3>Operating truth</h3><span class="badge">No shame math</span></div><div class="truth-list"><p><strong>${money(m.grossOutflow,true)}</strong><span>gross outflow from statements</span></p><p><strong>${money(m.protectedSavings,true)}</strong><span>saved or protected movement</span></p><p><strong>${money(m.spending,true)}</strong><span>actual spend pressure estimate</span></p></div></article><article class="card card-pad"><h3>Primary objective</h3>${goal?goalProgress(goal):`<p class="muted">Create a goal to connect Rank Mode with a target.</p>`}</article></aside></div>`}
function accountMini(x){return `<div class="transaction"><span class="tx-icon" style="background:${x.color}22;color:${x.color}">${esc(x.institution[0])}</span><div><strong>${esc(x.name)}</strong><small>${esc(x.kind)} · ${esc(x.type)}</small></div><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${money(x.balance)}</strong></div>`}
function pageHead(title,subtitle,action=""){return `<div class="page-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${action}</div>`}
function kpi(label,value,sub,cls=""){const display=typeof value==="string"?value:money(value,true);return `<article class="card kpi"><span class="eyebrow">${label}</span><div class="kpi-value privacy-amount" data-hidden="${state.profile.privacy}">${display}</div><span class="trend ${cls}">${sub}</span></article>`}
function cashflowChart(){const max=Math.max(...state.monthly.flatMap(x=>[x.income,x.expense]));return `<div class="chart">${state.monthly.map(x=>`<div class="bar-group" tabindex="0" aria-label="${x.m}: income ${money(x.income)}, spending ${money(x.expense)}"><div class="chart-tip"><strong>${x.m}</strong><span>Income <b class="positive">${money(x.income)}</b></span><span>Spending <b class="negative">${money(x.expense)}</b></span><span>Net <b>${signed(x.income-x.expense)}</b></span></div><i class="bar-income" style="height:${x.income/max*100}%"></i><i class="bar-expense" style="height:${x.expense/max*100}%"></i><span>${x.m}</span></div>`).join("")}</div><div class="chart-legend"><span><i class="dot" style="background:var(--accent)"></i>Income</span><span><i class="dot" style="background:var(--negative)"></i>Spending</span></div>`}
function txRow(x){const marker=x.type==="income"?"+":x.type==="transfer"?"":"-";return `<div class="transaction"><span class="tx-icon">${categoryIcon(x.category)}</span><div><strong>${esc(x.name)}</strong><small>${esc(x.category)} · ${esc(x.date)}</small></div><div class="amount ${x.type}">${marker}${money(x.amount)}</div></div>`}
function categoryIcon(c){return({Income:"↗",Food:"●",Housing:"⌂",Investment:"◇",Utilities:"⚡",Transport:"↔",Health:"+"}[c]||"•")}
function categoryRows(){const expenses=state.transactions.filter(x=>x.type==="expense"&&!isProtectedMovement(x)),total=sum(expenses,"amount")||1,groups={};expenses.forEach(x=>groups[x.category]=(groups[x.category]||0)+x.amount);const colors=["var(--accent)","var(--blue)","var(--warning)","var(--purple)","var(--negative)"];return Object.entries(groups).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([name,value],i)=>`<div class="category-row"><i class="category-swatch" style="background:${colors[i]}"></i><div><strong>${esc(name)}</strong><div class="progress"><span style="--value:${value/total*100}%;background:${colors[i]}"></span></div></div><span>${money(value,true)}</span></div>`).join("")||`<p class="muted">Protected savings are separated from spending. Review imported transfers to improve this map.</p>`}
function monthlyCommitments(){return state.subscriptions.filter(x=>x.active).reduce((n,x)=>n+x.amount/(x.cycle==="Yearly"?12:1),0)+state.loans.reduce((n,x)=>n+x.payment,0)}
function goalCurrency(goal){return goal?.currency||state.profile.currency}
function goalEditLimit(goal){return Math.max(0,Number(goal?.editLimit)||MAX_GOAL_EDITS)}
function goalEditsLeft(goal){return Math.max(0,goalEditLimit(goal)-(Number(goal?.editsUsed)||0))}
function goalDueDate(goal){const raw=String(goal?.due||"").trim();if(/^\d{4}-\d{2}$/.test(raw))return new Date(`${raw}-28T23:59:59`);if(/^\d{4}-\d{2}-\d{2}$/.test(raw))return new Date(`${raw}T23:59:59`);const parsed=new Date(raw);return Number.isNaN(parsed.getTime())?new Date(Date.now()+180*86400000):parsed}
function goalDaysLeft(goal){return Math.max(0,Math.ceil((goalDueDate(goal)-new Date())/86400000))}
function activeGoal(){return [...state.goals].sort((a,b)=>(a.priority||9)-(b.priority||9))[0]||null}
function goalProgress(goal){const currency=goalCurrency(goal),pct=Math.min(100,Math.round((Number(goal.saved)||0)/(Number(goal.target)||1)*100));return `<div class="goal-amount privacy-amount" data-hidden="${state.profile.privacy}"><strong>${moneyIn(goal.saved,currency)}</strong><span>of ${moneyIn(goal.target,currency)}</span></div><div class="progress"><span style="--value:${pct}%"></span></div><div class="loan-top"><small class="muted">${pct}% secured</small><small>Due ${esc(goal.due)}</small></div>`}
function pathMetrics(path,goal){const currency=goalCurrency(goal),sold=Math.max(0,Number(path.sold)||0),planned=Math.max(sold,Number(path.plannedSales)||0),offer=Math.max(0,Number(path.offer)||0),remaining=Math.max(0,planned-sold),soldValue=convertMoney(sold*offer,path.currency,currency),plannedValue=convertMoney(planned*offer,path.currency,currency),hours=remaining*Math.max(0,Number(path.hoursPerSale)||0),capacity=Math.max(0,Number(path.monthlyCapacity)||0)*Math.max(1,goalDaysLeft(goal)/30.44);return{sold,planned,remaining,soldValue,plannedValue,hours,capacity}}
function goalPlan(goal){const paths=state.incomePaths.map(path=>({path,...pathMetrics(path,goal)})),confirmed=paths.reduce((n,x)=>n+x.soldValue,0),forecast=paths.reduce((n,x)=>n+x.plannedValue,0),hours=paths.reduce((n,x)=>n+x.hours,0),days=goalDaysLeft(goal),weeks=Math.max(1,days/7),availableHours=weeks*Math.max(1,Number(state.profile.goalHoursWeek)||1),gap=Math.max(0,Number(goal.target)-Number(goal.saved)-confirmed),forecastGap=Math.max(0,Number(goal.target)-Number(goal.saved)-forecast);return{paths,confirmed,forecast,hours,days,weeks,availableHours,gap,forecastGap,coverage:Math.min(999,Math.round((Number(goal.saved)+forecast)/(Number(goal.target)||1)*100))}}
function upcomingRows(limit=8){const items=[...state.subscriptions.filter(x=>x.active).map(x=>({name:x.name,detail:`Subscription · ${x.next}`,amount:x.amount,type:"out"})),...state.loans.map(x=>({name:x.name,detail:`Loan payment · ${x.due}`,amount:x.payment,type:"out"})),...state.loansGiven.map(x=>({name:x.name,detail:`Expected collection · ${x.due}`,amount:x.payment,type:"in"}))].slice(0,limit);return items.map(x=>`<div class="transaction"><span class="tx-icon">${x.type==="in"?"↙":"↗"}</span><div><strong>${esc(x.name)}</strong><small>${esc(x.detail)}</small></div><strong class="${x.type==="in"?"positive":"negative"}">${x.type==="in"?"+":"-"}${money(x.amount)}</strong></div>`).join("")}
function advisorData(){const t=totals(),available=sum(state.accounts,"balance"),avgExpense=state.monthly.reduce((n,x)=>n+x.expense,0)/state.monthly.length,runway=available/(avgExpense||1),pace=Math.round(t.expense/state.profile.monthlyBudget*100),highLoan=[...state.loans].sort((a,b)=>b.rate-a.rate)[0],recurring=monthlyCommitments(),ratio=t.income?Math.round(recurring/t.income*100):0,actions=[];if(pace>100)actions.push({level:"urgent",title:"Pause flexible spending",text:`Recorded spending is ${pace-100}% above your monthly guardrail. Slow Food, Entertainment, and Other spending until the next income event.`,impact:`Recover ${money(Math.max(0,t.expense-state.profile.monthlyBudget))}`});else if(pace>80)actions.push({level:"watch",title:"Ease your spending pace",text:`You have used ${pace}% of your monthly guardrail. Delay non-essential purchases before the limit becomes a shortfall.`,impact:`Keep ${money(Math.max(0,state.profile.monthlyBudget-t.expense))} available`});if(runway<3)actions.push({level:"urgent",title:"Build a three-month reserve",text:`Your liquid accounts cover about ${runway.toFixed(1)} months of typical spending. Prioritize cash resilience before aggressive investing.`,impact:`Gap: ${money(Math.max(0,avgExpense*3-available))}`});if(highLoan?.rate>15)actions.push({level:"watch",title:`Target ${highLoan.name}`,text:`At ${highLoan.rate}% APR, this is your most expensive borrowed balance. Extra payments here have the clearest guaranteed return.`,impact:`Balance: ${money(highLoan.balance)}`});if(ratio>25)actions.push({level:"watch",title:"Reduce fixed commitments",text:`Loans and subscriptions consume ${ratio}% of recorded income before everyday spending begins.`,impact:`Review ${money(recurring)} monthly`});const goal=activeGoal();if(goal){const currency=goalCurrency(goal),suggested=convertMoney(Math.max(100,t.cashflow*.25),state.profile.currency,currency);actions.push({level:"good",title:`Advance ${goal.name}`,text:`A contribution of ${moneyIn(Math.min(goal.target-goal.saved,suggested),currency)} keeps this goal moving without using all current surplus.`,impact:`${Math.round(goal.saved/goal.target*100)}% secured`})}if(!actions.length)actions.push({level:"good",title:"Keep the system steady",text:"Cashflow, reserves, and commitments are currently balanced. Continue recording activity so FinMax can detect changes early.",impact:"No urgent action"});return actions}
function goals(){const goal=activeGoal(),actions=`<div class="goal-page-actions"><button class="btn" data-open="incomePath">+ Income path</button><button class="btn primary" data-open="goal">+ Financial goal</button></div>`;if(!goal)return `${pageHead("Goals","Build a measurable route from today to the number that matters.",actions)}<article class="card empty-goal"><span class="eyebrow">Start here</span><h2>Create your first financial goal</h2><p>Choose a currency and deadline. FinMax will calculate the pace required without sending anything online.</p><button class="btn primary" data-open="goal">Create goal</button></article>`;const currency=goalCurrency(goal),plan=goalPlan(goal),secured=Number(goal.saved)||0,pct=Math.min(100,Math.round(secured/(Number(goal.target)||1)*100)),weekly=plan.gap/plan.weeks,other=currency==="USD"?"NGN":"USD",converted=convertMoney(goal.target,currency,other),capacityOver=plan.hours>plan.availableHours,covered=plan.forecastGap<=0;return `${pageHead("Goal Lab","One target, multiple editable routes, and no hidden arithmetic.",actions)}<section class="goal-command"><div class="goal-command-main"><div class="goal-command-top"><div><span class="eyebrow">Primary goal · ${esc(goal.type)} · ${currency}</span><h2>${esc(goal.name)}</h2></div><span class="goal-deadline">${plan.days} days left</span></div><div class="goal-total privacy-amount" data-hidden="${state.profile.privacy}"><strong>${moneyIn(secured,currency)}</strong><span>/ ${moneyIn(goal.target,currency)}</span></div><div class="progress goal-master-progress"><span style="--value:${pct}%"></span></div><div class="goal-command-meta"><span>${pct}% secured</span><span>Target equals ${moneyIn(converted,other,true)} at your current rate</span></div></div><aside class="goal-pace"><span class="eyebrow">Required pace from here</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(weekly,currency,true)}</strong><span>per week</span><small>Sales won reduce the remaining pace even before cash is assigned.</small></aside></section><section class="goal-settings-bar"><label><span>Offline exchange rate</span><div class="inline-rate"><b>1 USD =</b><input type="number" min="1" step="1" value="${state.profile.fxUsdNgn}" data-goal-config="fxUsdNgn"><b>NGN</b></div></label><label><span>Time available around school</span><div class="inline-rate"><input type="number" min="1" max="168" step="1" value="${state.profile.goalHoursWeek}" data-goal-config="goalHoursWeek"><b>hours / week</b></div></label><p>Both values stay on this device. Update the rate whenever you choose.</p></section><div class="grid goal-kpis"><article><span>Income already won</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(plan.confirmed,currency,true)}</strong><small>From logged path sales</small></article><article><span>Planned path value</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(plan.forecast,currency,true)}</strong><small>${plan.coverage}% total goal coverage</small></article><article><span>Work required</span><strong>${Math.round(plan.hours)}h</strong><small>of ${Math.round(plan.availableHours)}h available</small></article><article class="${covered&&!capacityOver?"plan-good":"plan-watch"}"><span>Plan signal</span><strong>${!covered?"Revenue gap":capacityOver?"Over capacity":"Covered"}</strong><small>${!covered?`${moneyIn(plan.forecastGap,currency,true)} still unassigned`:capacityOver?`${Math.round(plan.hours-plan.availableHours)}h beyond your limit`:"The route works on paper"}</small></article></div><div class="section-title goal-section-title"><div><span class="eyebrow">Income architecture</span><h2>Your routes to the goal</h2></div><span class="muted">Add, edit, remove, or log one sale</span></div><div class="grid three-col income-path-grid">${state.incomePaths.map(path=>incomePathCard(path,goal)).join("")||`<article class="card empty-goal"><h3>No income paths yet</h3><p>Add the offers or products you are building.</p><button class="btn primary" data-open="incomePath">Add income path</button></article>`}</div><div class="section-title goal-section-title"><div><span class="eyebrow">Goal portfolio</span><h2>All financial goals</h2></div></div><div class="grid two-col">${[...state.goals].sort((a,b)=>(a.priority||9)-(b.priority||9)).map(g=>`<article class="card goal-card"><div class="card-head"><div><span class="eyebrow">Priority ${g.priority} · ${esc(g.type)} · ${goalCurrency(g)}</span><h2>${esc(g.name)}</h2></div><span class="badge ${g.id===goal.id?"active":""}">${Math.round((g.saved||0)/(g.target||1)*100)}%</span></div>${goalProgress(g)}<div class="goal-actions"><button class="btn" data-primary-goal="${g.id}">${g.id===goal.id?"Primary goal":"Make primary"}</button><button class="btn primary" data-contribute-goal="${g.id}">Add contribution</button><button class="btn danger" data-delete-goal="${g.id}">Remove</button></div></article>`).join("")}</div>`}
function incomePathCard(path,goal){const m=pathMetrics(path,goal),currency=goalCurrency(goal),pct=m.planned?Math.min(100,Math.round(m.sold/m.planned*100)):0,capacityWarning=m.remaining>m.capacity;return `<article class="card income-path-card"><div class="path-accent"></div><div class="card-head"><div><span class="eyebrow">${esc(path.status)} · ${path.currency}</span><h3>${esc(path.name)}</h3></div><button class="btn small" data-edit-path="${path.id}">Edit</button></div><div class="path-price privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(path.offer,path.currency)} <span>per sale</span></div><div class="path-stats"><div><span>Sales</span><strong>${m.sold} / ${m.planned}</strong></div><div><span>Plan value</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(m.plannedValue,currency,true)}</strong></div><div><span>Hours left</span><strong>${Math.round(m.hours)}h</strong></div></div><div class="progress"><span style="--value:${pct}%"></span></div>${capacityWarning?`<p class="path-warning">Planned sales exceed this path's current delivery capacity before the deadline.</p>`:`<p class="muted">About ${Math.round(m.capacity)} sales fit your stated monthly capacity.</p>`}<div class="path-actions"><button class="btn primary" data-log-path-sale="${path.id}">+ Log one sale</button><button class="btn danger" data-delete-path="${path.id}">Remove</button></div></article>`}
function advisor(){const actions=advisorData();return `${pageHead("FinMax Advisor","Clear, explainable guidance based on the numbers stored on this device.")}<article class="card advisor-hero"><div><span class="eyebrow">Recommended now</span><h2>${actions[0].title}</h2><p>${actions[0].text}</p></div><strong>${actions[0].impact}</strong></article><div class="grid two-col" style="margin-top:16px"><section><div class="section-title"><div><span class="eyebrow">Action plan</span><h2>Prioritized guidance</h2></div></div><div class="grid">${actions.map((a,i)=>`<article class="card advice-card ${a.level}"><span class="advice-number">${i+1}</span><div><h3>${a.title}</h3><p>${a.text}</p><strong>${a.impact}</strong></div></article>`).join("")}</div></section><section><div class="section-title"><div><span class="eyebrow">Financial calendar</span><h2>What is approaching</h2></div></div><article class="card card-pad">${upcomingRows()}</article></section></div><p class="advisor-note">FinMax advice is generated from your offline records and simple explainable rules. It is guidance, not professional financial advice.</p>`}

function accounts(){const personal=state.accounts.filter(x=>x.kind==="Personal"),business=state.accounts.filter(x=>x.kind==="Business");return `${pageHead("Accounts","Keep personal money, business money, mobile wallets, banks, and cash distinct.",`<button class="btn primary" data-open="account">+ Add account</button>`)}<div class="grid kpi-grid">${kpi("All account balances",sum(state.accounts,"balance"),`${state.accounts.length} offline accounts`)}${kpi("Personal",sum(personal,"balance"),`${personal.length} accounts`)}${kpi("Business",sum(business,"balance"),`${business.length} accounts`)}${kpi("Cash on hand",sum(state.accounts.filter(x=>x.type==="Cash"),"balance"),"Physical cash ledger")}</div><div class="grid three-col">${state.accounts.map(x=>`<article class="card account-card"><div class="account-color" style="background:${x.color}"></div><div class="loan-top"><div><span class="eyebrow">${esc(x.institution)}</span><h3>${esc(x.name)}</h3></div><span class="badge ${x.kind==="Business"?"active":""}">${esc(x.kind)}</span></div><div class="account-balance privacy-amount" data-hidden="${state.profile.privacy}">${money(x.balance)}</div><div class="muted">${esc(x.type)}</div><div class="account-actions"><button class="btn small" data-open-account-tx="${x.id}">Add activity</button><button class="btn small danger" data-delete-account="${x.id}">Remove</button></div></article>`).join("")}</div>`}

function transactions(){const rows=state.transactions.filter(x=>!search||`${x.name} ${x.category} ${x.account}`.toLowerCase().includes(search.toLowerCase()));return `${pageHead("Transactions","Every movement, searchable and editable.",`<button class="btn primary" data-open="transaction">+ New transaction</button>`)}<div class="table-tools"><input class="search" data-search value="${esc(search)}" placeholder="Search merchant, category, or account"><button class="btn" data-action="export">Export</button></div><article class="card table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Account</th><th>Type</th><th>Amount</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.date)}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.category)}</td><td>${esc(x.account)}</td><td><span class="badge ${x.type==="income"?"active":""}">${x.type}</span></td><td class="amount ${x.type}">${x.type==="income"?"+":"-"}${money(x.amount)}</td><td><button class="btn small danger" data-delete-tx="${x.id}">Delete</button></td></tr>`).join("")}</tbody></table></article>`}
function review(){const items=state.reviewQueue||[];return `${pageHead("Transaction Review","Imported statement lines stay here until you explain what they really mean.",`<button class="btn primary" data-open="transaction">Log manual item</button>`)}<div class="grid two-col review-layout"><article class="card card-pad"><div class="card-head"><div><h3>Needs judgement</h3><span class="muted">${items.length} pending imported ${items.length===1?"item":"items"}</span></div><span class="badge ${items.length?"":"active"}">${items.length?"Review mode":"Clear"}</span></div><div class="review-list">${items.map(reviewRow).join("")||`<div class="empty-review"><strong>All clear.</strong><p class="muted">New ambiguous imports will appear here first, then move to Transactions after approval.</p></div>`}</div></article><aside class="grid"><article class="card card-pad"><span class="eyebrow">How this protects you</span><h3>Not every debit is spending.</h3><p class="muted">Savings deposits, POS cash withdrawals, family loans, and pass-through transfers need context. FinMax waits for your approval before counting them in the main ledger.</p></article><article class="card card-pad"><h3>Classification rules</h3><div class="truth-list"><p><strong>Savings</strong><span>excluded from spending pressure</span></p><p><strong>Loan given</strong><span>tracks money expected back</span></p><p><strong>Expense</strong><span>counts against your guardrail</span></p></div></article></aside></div>`}
function reviewRow(x){const account=state.accounts.find(a=>a.id===x.accountId);return `<div class="review-item"><div><span class="eyebrow">${esc(x.date)} · ${esc(account?.name||"Unassigned")}</span><h3>${esc(x.name)}</h3><p>${esc(x.note||"No note yet.")}</p><div class="review-tags"><span>${esc(x.suggestedType)}</span><span>${esc(x.suggestedCategory)}</span><strong>${money(x.amount)}</strong></div></div><div class="review-actions"><button class="btn small" data-edit-review="${x.id}">Update</button><button class="btn small primary" data-approve-review="${x.id}">Approve</button></div></div>`}

function wealth(){const t=totals(),cash=sum(state.accounts,"balance");return `${pageHead("Net worth","The complete balance sheet behind your choices.",`<button class="btn" data-open="asset">+ Add position</button>`)}<article class="card wealth-hero"><span class="eyebrow">Total net worth</span><div class="wealth-value privacy-amount" data-hidden="${state.profile.privacy}">${money(t.netWorth)}</div><p class="positive">Assets exceed liabilities by ${money(t.netWorth,true)}</p><div class="allocation"><span style="width:${cash/t.assets*100}%;background:var(--accent)"></span>${state.assets.map((x,i)=>`<span style="width:${x.value/t.assets*100}%;background:${["var(--blue)","var(--purple)","var(--warning)"][i%3]}"></span>`).join("")}</div></article><div class="grid two-col" style="margin-top:16px"><article class="card card-pad"><div class="card-head"><div><h3>Assets</h3><span class="positive">${money(t.assets)}</span></div><button class="btn small" data-open="asset">Add</button></div><div class="asset-list"><div class="asset-row"><div><strong>Cash across accounts</strong><small class="muted">${state.accounts.length} account ledgers</small></div><strong>${money(cash)}</strong><button class="btn small" data-view="accounts">View</button></div>${state.assets.map(x=>assetRow(x,"asset")).join("")}</div></article><article class="card card-pad"><div class="card-head"><div><h3>Liabilities</h3><span class="negative">${money(t.liabilities)}</span></div><button class="btn small" data-open="liability">Add</button></div><div class="asset-list">${state.liabilities.map(x=>assetRow(x,"liability")).join("")}</div></article></div>`}
function assetRow(x,kind){return `<div class="asset-row"><div><strong>${esc(x.name)}</strong><small class="muted">${esc(x.type)}</small></div><strong>${money(x.value)}</strong><button class="btn small danger" data-delete-position="${kind}|${x.id}">Remove</button></div>`}

function loans(){const owed=sum(state.loans,"balance"),receivable=sum(state.loansGiven,"balance"),payments=sum(state.loans,"payment"),incoming=sum(state.loansGiven,"payment");return `${pageHead("Loans","Money you owe and money owed to you, without mixing the two.",`<button class="btn" data-open="loan">+ Add loan</button>`)}<div class="grid kpi-grid">${kpi("I owe",owed,"Borrowed balances","negative")}${kpi("Owed to me",receivable,"Outstanding receivables","positive")}${kpi("Monthly outflow",payments,"Scheduled repayments")}${kpi("Expected inflow",incoming,"Expected collections","positive")}</div><div class="grid loan-columns"><section><div class="section-title"><div><span class="eyebrow">Borrowed by me</span><h2>My obligations</h2></div><span class="badge">${state.loans.length} active</span></div><div class="grid">${state.loans.map(x=>loanCard(x,"borrowed")).join("")}</div></section><section><div class="section-title"><div><span class="eyebrow">Lent by me</span><h2>My receivables</h2></div><span class="badge active">${state.loansGiven.length} active</span></div><div class="grid">${state.loansGiven.map(x=>loanCard(x,"lent")).join("")}</div></section></div>`}
function loanCard(x,direction){const party=direction==="borrowed"?x.lender:x.borrower,done=Math.round((1-x.balance/x.original)*100);return `<article class="card loan-card"><div class="loan-top"><div><span class="eyebrow">${direction==="borrowed"?"Lender":"Borrower"}: ${esc(party)}</span><h3>${esc(x.name)}</h3></div><span class="badge ${direction==="lent"?"active":""}">${x.rate}% APR</span></div><div class="loan-balance">${money(x.balance)}</div><div class="progress"><span style="--value:${Math.max(2,done)}%"></span></div><div class="loan-top"><small class="muted">${done}% settled</small><small>Due ${esc(x.due)}</small></div><button class="btn ${direction==="borrowed"?"primary":""}" ${direction==="borrowed"?`data-pay-loan="${x.id}"`:`data-collect-loan="${x.id}"`}>${direction==="borrowed"?"Record payment":"Record collection"} · ${money(x.payment)}</button></article>`}
function weightedRate(){const total=sum(state.loans,"balance")||1;return `${(state.loans.reduce((n,x)=>n+x.rate*x.balance,0)/total).toFixed(1)}%`}

function subscriptions(){const active=state.subscriptions.filter(x=>x.active),monthly=active.reduce((n,x)=>n+x.amount/(x.cycle==="Yearly"?12:1),0);return `${pageHead("Subscriptions","Recurring costs, without quiet leaks.",`<button class="btn" data-open="subscription">+ Add subscription</button>`)}<div class="grid kpi-grid">${kpi("Monthly total",monthly,"Normalized recurring cost")}${kpi("Annual run rate",monthly*12,"If nothing changes")}${kpi("Active services",String(active.length),`${state.subscriptions.length-active.length} paused`)}${kpi("Largest recurring",Math.max(0,...active.map(x=>x.amount)),"Current billing amount")}</div><div class="grid three-col">${state.subscriptions.map(x=>`<article class="card sub-card ${x.active?"":"inactive"}"><div class="sub-top"><span class="sub-logo">${esc(x.name[0])}</span><button class="btn small" data-toggle-sub="${x.id}">${x.active?"Pause":"Resume"}</button></div><div><h3>${esc(x.name)}</h3><span class="muted">${esc(x.category)}</span></div><div class="loan-top"><strong>${money(x.amount)} / ${x.cycle==="Yearly"?"yr":"mo"}</strong><small>Next ${esc(x.next)}</small></div></article>`).join("")}</div>`}

function analytics(){const t=totals(),available=sum(state.accounts,"balance"),avgExpense=state.monthly.reduce((n,x)=>n+x.expense,0)/state.monthly.length,rate=t.income?Math.round(t.cashflow/t.income*100):0,runway=avgExpense?available/avgExpense:0,debtRatio=t.assets?Math.round(t.liabilities/t.assets*100):0,recurring=monthlyCommitments(),recurringRatio=t.income?Math.round(recurring/t.income*100):0,health=Math.max(0,Math.min(100,Math.round(45+rate*.6+Math.min(runway,6)*4-debtRatio*.25-recurringRatio*.2))),projection=t.netWorth+t.cashflow*6,largest=[...state.transactions.filter(x=>x.type==="expense")].sort((a,b)=>b.amount-a.amount)[0];return `${pageHead("Analytics","A decision layer for cashflow, resilience, debt, and future wealth.")}<div class="grid kpi-grid">${kpi("Financial health",`${health}/100`,health>=75?"Strong operating position":"Room to improve",health>=75?"positive":"")}${kpi("Liquidity runway",`${runway.toFixed(1)} mo`,"At average monthly spending")}${kpi("Debt-to-assets",`${debtRatio}%`,debtRatio<40?"Within a healthy range":"Review leverage",debtRatio<40?"positive":"negative")}${kpi("Recurring pressure",`${recurringRatio}%`,`${money(recurring)} monthly committed`)}</div><div class="grid dash-grid"><article class="card card-pad"><div class="card-head"><div><h3>Income and spending</h3><span class="muted">Hover or focus a month for exact values</span></div><span class="badge active">6 months</span></div>${cashflowChart()}</article><aside class="grid"><article class="card card-pad"><span class="eyebrow">Six-month net-worth projection</span><div class="kpi-value positive">${money(projection,true)}</div><p class="muted">If recorded cashflow continues without market growth.</p><div class="progress"><span style="--value:${Math.min(100,Math.max(5,rate))}%"></span></div></article><article class="card card-pad"><span class="eyebrow">Largest recorded expense</span><div class="kpi-value">${largest?money(largest.amount):money(0)}</div><span class="muted">${largest?esc(largest.name):"No expenses"}</span></article></aside></div><div class="grid two-col" style="margin-top:16px"><article class="card card-pad"><div class="card-head"><h3>Spending concentration</h3><span class="muted">Where flexibility exists</span></div>${categoryRows()}</article><article class="card card-pad"><div class="card-head"><h3>Recommended next moves</h3><span class="badge active">Prioritized</span></div><div class="grid"><div class="insight"><strong>${runway<3?"Build liquidity first":"Protect your runway"}</strong><p>${runway<3?`Move toward at least three months of spending. The current gap is ${money(Math.max(0,avgExpense*3-available))}.`:`Your ${runway.toFixed(1)}-month runway is healthy. Keep its cash separate from investment capital.`}</p></div><div class="insight"><strong>${debtRatio>40?"Reduce leverage":"Use surplus deliberately"}</strong><p>${debtRatio>40?"Debt is taking a large share of assets. Prioritize the highest-rate balance.":`Allocating 50% of current surplus could add ${money(t.cashflow*6)} to investments in one year.`}</p></div><div class="insight"><strong>Review recurring commitments</strong><p>${recurringRatio}% of recorded income is committed before flexible spending. Pause services that no longer earn their place.</p></div></div></article></div>`}

function settings(){return `${pageHead("Customize","Make the interface fit the way you think about money.")}<div class="grid settings-grid"><article class="card card-pad"><div class="setting-row"><div><strong>Experience mode</strong><p class="muted">Everyday is simple, Executive is complete, Rank turns review and recovery into progress.</p></div><div class="segmented"><button class="${state.profile.mode==="everyday"?"active":""}" data-mode="everyday">Everyday</button><button class="${state.profile.mode==="executive"?"active":""}" data-mode="executive">Executive</button><button class="${state.profile.mode==="rank"?"active":""}" data-mode="rank">Rank</button></div></div><div class="setting-row"><div><strong>Monthly spending guardrail</strong><p class="muted">Used by Everyday mode to warn when spending accelerates.</p></div><input class="setting-input" type="number" value="${state.profile.monthlyBudget}" data-profile-number="monthlyBudget"></div><div class="setting-row"><div><strong>Reserve target</strong><p class="muted">Cash amount FinMax should protect before calling money safe to spend.</p></div><input class="setting-input" type="number" value="${state.profile.reserveTarget}" data-profile-number="reserveTarget"></div><div class="setting-row"><div><strong>Appearance</strong><p class="muted">Follow your system or choose a fixed theme.</p></div><div class="segmented">${["light","dark","system"].map(x=>`<button class="${state.profile.theme===x?"active":""}" data-theme="${x}">${x}</button>`).join("")}</div></div><div class="setting-row"><div><strong>Accent</strong><p class="muted">Choose a restrained signature color.</p></div><div class="swatches"><button class="swatch ${state.profile.accent==="green"?"active":""}" style="background:#176b5b" data-accent="green"></button><button class="swatch ${state.profile.accent==="blue"?"active":""}" style="background:#356bd6" data-accent="blue"></button><button class="swatch ${state.profile.accent==="plum"?"active":""}" style="background:#7656a7" data-accent="plum"></button></div></div><div class="setting-row"><div><strong>Information density</strong><p class="muted">Comfortable or compact workspace.</p></div><div class="segmented"><button class="${state.profile.density===1?"active":""}" data-density="1">Comfort</button><button class="${state.profile.density===.9?"active":""}" data-density=".9">Compact</button></div></div></article><aside class="grid"><article class="card card-pad"><h3>${state.profile.mode==="everyday"?"Advanced tools":state.profile.mode==="rank"?"Rank toolkit":"Offline data vault"}</h3><p class="muted">${state.profile.mode==="everyday"?"Open the deeper workspaces without changing your daily navigation.":state.profile.mode==="rank"?"Review imported lines, protect savings movements, and replay the tutorial any time.":"Everything stays in this browser. Export a backup before clearing browser data."}</p><div class="grid">${state.profile.mode==="everyday"?`<button class="btn" data-view="accounts">Accounts</button><button class="btn" data-view="loans">Loans and receivables</button><button class="btn" data-view="subscriptions">Subscriptions</button><button class="btn" data-view="analytics">Full analytics</button>`:""}<button class="btn" data-view="review">Transaction review</button><button class="btn" data-action="tutorial">Replay tutorial</button><button class="btn primary" data-action="export">Export encrypted-ready JSON</button><button class="btn" data-action="import">Import backup</button><button class="btn" data-action="logout">Sign out</button><button class="btn danger" data-action="reset">Reset imported data</button></div></article></aside></div>`}

function tutorial(){const steps=[
  {icon:"▤",title:"Your accounts stay separate",text:"Add PalmPay, Moniepoint, business accounts, personal accounts, and cash. Each keeps its own balance."},
  {icon:"↔",title:"Transactions do the bookkeeping",text:"Choose an account when logging income or spending. FinMax updates that account automatically."},
  {icon:"◇",title:"See the full financial picture",text:"Assets, debts, loans, subscriptions, and account balances come together without mixing their roles."},
  {icon:"◌",title:"Make FinMax yours",text:"Switch Everyday or Executive views, hide balances in public, choose a theme, and export a private backup."}
],s=steps[tutorialStep];return `<div class="tutorial-backdrop"><section class="tutorial-card"><div class="tutorial-progress">${steps.map((_,i)=>`<i class="${i<=tutorialStep?"active":""}"></i>`).join("")}</div><div class="tutorial-icon">${s.icon}</div><span class="eyebrow">FinMax tutorial · ${tutorialStep+1} of ${steps.length}</span><h2>${s.title}</h2><p>${s.text}</p><div class="tutorial-actions"><button class="btn" data-tutorial="skip">Skip</button><button class="btn primary" data-tutorial="${tutorialStep===steps.length-1?"finish":"next"}">${tutorialStep===steps.length-1?"Start using FinMax":"Continue"}</button></div></section></div>`}

function modalView(){const forms={transaction:transactionForm,review:reviewForm,account:accountForm,goal:goalForm,incomePath:incomePathForm,asset:()=>positionForm("asset"),liability:()=>positionForm("liability"),loan:loanForm,subscription:subscriptionForm};return `<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true">${forms[modal]()}</section></div>`}
function modalHeader(title,sub){return `<div class="card-head"><div><h2>${title}</h2><p class="muted">${sub}</p></div><button class="btn icon" type="button" data-close-modal>×</button></div>`}
function transactionForm(){return `${modalHeader("Add transaction","Record income or spending in seconds.")}<form data-form="transaction"><div class="form-grid"><div class="field full"><label>Description</label><input name="name" required placeholder="Merchant or source"></div><div class="field"><label>Amount</label><input name="amount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Type</label><select name="type"><option value="expense">Expense</option><option value="income">Income</option></select></div><div class="field"><label>Category</label><select name="category">${["Food","Housing","Utilities","Transport","Health","Data/Airtime","Savings","Investment","Loan","Loan Repayment","Subscription","Fees","Income","Other"].map(x=>`<option>${x}</option>`).join("")}</select></div><div class="field"><label>Account</label><select name="accountId" required>${state.accounts.map(x=>`<option value="${x.id}" ${state.pendingAccount===x.id?"selected":""}>${esc(x.name)} · ${money(x.balance)}</option>`).join("")}</select></div><div class="field full"><label>Date</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div></div>${modalActions()}</form>`}
function reviewForm(){
  const item=state.reviewQueue.find(x=>x.id===reviewingId)||state.reviewQueue[0],account=state.accounts.find(a=>a.id===item?.accountId),raw=statementRawDescription(item),pdf=reviewPdfLabel(item);
  return `${modalHeader("Update imported item","Add the context FinMax cannot infer from a PDF line.")}<form data-form="review"><input name="id" value="${esc(item?.id||"")}" hidden><div class="form-grid">${raw?`<div class="field full"><label>Original PDF narration</label><input readonly value="${esc(raw)}"></div>`:""}<div class="field full"><label>Your corrected description</label><input name="name" required value="${esc(item?.name||"")}" placeholder="What really happened?"></div><div class="field"><label>Amount</label><input name="amount" type="number" min="0.01" step="0.01" required value="${item?.amount||0}"></div><div class="field"><label>Type</label><select name="type">${["expense","income","transfer","loan-given","loan-received"].map(x=>`<option value="${x}" ${item?.suggestedType===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Category</label><select name="category">${["Transport","Food","Data/Airtime","Savings","Loan","Loan Repayment","Transfer Review","Subscription","Fees","Income","Other"].map(x=>`<option ${item?.suggestedCategory===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Account</label><select name="accountId">${state.accounts.map(x=>`<option value="${x.id}" ${item?.accountId===x.id?"selected":""}>${esc(x.name)}</option>`).join("")}</select></div><div class="field"><label>Date</label><input name="date" type="date" value="${esc(item?.date||new Date().toISOString().slice(0,10))}"></div><div class="field"><label>Source</label><input readonly value="${esc(smartSourceName(pdf))} - ${esc(accountShortName(account))}"></div><div class="field full"><label>Private note</label><input name="note" value="${esc(item?.note||"")}" placeholder="Example: POS cash for school transport, charged 100 NGN"></div></div><p class="muted">Approving does not change account balances again; these are historical imports whose balances are already reflected in the statements.</p>${modalActions()}</form>`;
}
function accountForm(){return `${modalHeader("Add account","Create a separate ledger for a bank, wallet, business, or cash.")}<form data-form="account"><div class="form-grid"><div class="field full"><label>Account name</label><input name="name" required placeholder="e.g. Moniepoint Business"></div><div class="field"><label>Institution</label><input name="institution" required placeholder="Bank, wallet, or Cash"></div><div class="field"><label>Use</label><select name="kind"><option>Personal</option><option>Business</option></select></div><div class="field"><label>Account type</label><select name="type"><option>Bank</option><option>Mobile money</option><option>Cash</option><option>Investment</option><option>Other</option></select></div><div class="field"><label>Opening balance</label><input name="balance" type="number" step="0.01" value="0" required></div><div class="field"><label>Color</label><input name="color" type="color" value="#176b5b"></div></div>${modalActions()}</form>`}
function goalForm(){return `${modalHeader("Create financial goal","FinMax will calculate the pace and compare it with your income paths.")}<form data-form="goal"><div class="form-grid"><div class="field full"><label>Goal name</label><input name="name" required placeholder="$1M, emergency reserve, home deposit..."></div><div class="field"><label>Goal type</label><select name="type"><option>Business</option><option>Growth</option><option>Safety</option><option>Debt</option><option>Purchase</option></select></div><div class="field"><label>Goal currency</label><select name="currency"><option>USD</option><option>NGN</option></select></div><div class="field"><label>Priority</label><select name="priority"><option value="1">High</option><option value="2">Medium</option><option value="3">Low</option></select></div><div class="field"><label>Target amount</label><input name="target" type="number" min="1" step="0.01" required></div><div class="field"><label>Already secured</label><input name="saved" type="number" min="0" step="0.01" value="0"></div><div class="field full"><label>Exact target date</label><input name="due" type="date" required></div></div>${modalActions()}</form>`}
function incomePathForm(){const path=state.incomePaths.find(x=>x.id===editingPathId);return `${modalHeader(path?"Edit income path":"Add income path","Model one service, product, or revenue stream without merging its economics with the others.")}<form data-form="income-path"><input name="id" value="${esc(path?.id||"")}" hidden><div class="form-grid"><div class="field full"><label>Path name</label><input name="name" required value="${esc(path?.name||"")}" placeholder="Wedding stationery design"></div><div class="field"><label>Charge in</label><select name="currency"><option ${path?.currency==="USD"?"selected":""}>USD</option><option ${path?.currency==="NGN"?"selected":""}>NGN</option></select></div><div class="field"><label>Price per sale</label><input name="offer" type="number" min="0.01" step="0.01" required value="${path?.offer??""}"></div><div class="field"><label>Planned sales</label><input name="plannedSales" type="number" min="1" step="1" required value="${path?.plannedSales??1}"></div><div class="field"><label>Sales already won</label><input name="sold" type="number" min="0" step="1" required value="${path?.sold??0}"></div><div class="field"><label>Hours per sale</label><input name="hoursPerSale" type="number" min="0" step="0.1" required value="${path?.hoursPerSale??1}"></div><div class="field"><label>Maximum sales per month</label><input name="monthlyCapacity" type="number" min="0" step="1" required value="${path?.monthlyCapacity??1}"></div><div class="field full"><label>Current status</label><select name="status">${["Idea","Preparing","Building","Selling","Paused"].map(x=>`<option ${path?.status===x?"selected":""}>${x}</option>`).join("")}</select></div></div>${modalActions()}</form>`}
function positionForm(kind){return `${modalHeader(`Add ${kind}`,"Update your private balance sheet.")}<form data-form="position" data-kind="${kind}"><div class="form-grid"><div class="field full"><label>Name</label><input name="name" required></div><div class="field"><label>Type</label><input name="type" required placeholder="Cash, property, credit..."></div><div class="field"><label>Current value</label><input name="value" type="number" min="0" step="0.01" required></div></div>${modalActions()}</form>`}
function loanForm(){return `${modalHeader("Add loan","Track borrowed money or money you lent out.")}<form data-form="loan"><div class="form-grid"><div class="field full"><label>Direction</label><select name="direction"><option value="borrowed">I borrowed this money</option><option value="lent">I lent this money out</option></select></div><div class="field"><label>Loan name</label><input name="name" required></div><div class="field"><label>Lender or borrower</label><input name="party" required></div><div class="field"><label>Current balance</label><input name="balance" type="number" min="0" required></div><div class="field"><label>Original amount</label><input name="original" type="number" min="0" required></div><div class="field"><label>APR %</label><input name="rate" type="number" min="0" step="0.1" required></div><div class="field"><label>Payment amount</label><input name="payment" type="number" min="0" required></div></div>${modalActions()}</form>`}
function subscriptionForm(){return `${modalHeader("Add subscription","Make the next recurring charge visible.")}<form data-form="subscription"><div class="form-grid"><div class="field full"><label>Service</label><input name="name" required></div><div class="field"><label>Amount</label><input name="amount" type="number" min="0" step="0.01" required></div><div class="field"><label>Category</label><input name="category" value="Other"></div><div class="field"><label>Cycle</label><select name="cycle"><option>Monthly</option><option>Yearly</option></select></div><div class="field"><label>Next billing</label><input name="next" placeholder="Jul 15"></div></div>${modalActions()}</form>`}
function modalActions(){return `<div class="modal-actions"><button class="btn" type="button" data-close-modal>Cancel</button><button class="btn primary">Save</button></div>`}

function greeting(){const h=new Date().getHours();return h<12?"morning":h<17?"afternoon":"evening"}
function toast(message){const n=document.createElement("div");n.className="toast";n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),2900)}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`finmax-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast("Backup exported")}

document.addEventListener("click",e=>{
  const tutorial=e.target.closest("[data-tutorial]");if(tutorial){if(tutorial.dataset.tutorial==="next"){tutorialStep++;render()}else{state.profile.tutorialDone=true;tutorialStep=0;save();render();toast("Tutorial complete")};return}
  const auth=e.target.closest("button[data-auth-mode]");if(auth){authMode=auth.dataset.authMode;localStorage.setItem("finmax_auth_mode",authMode);render();return}
  const reveal=e.target.closest("[data-toggle-password]");if(reveal){const input=reveal.parentElement.querySelector("input");if(input){input.type=input.type==="password"?"text":"password";reveal.textContent=input.type==="password"?"Show":"Hide";input.focus()}return}
  const v=e.target.closest("[data-view]");if(v)return route(v.dataset.view);
  const o=e.target.closest("[data-open]");if(o){if(o.dataset.open==="incomePath")editingPathId=null;if(o.dataset.open==="goal")editingGoalId=null;if(o.dataset.open==="subscription")editingSubscriptionId=null;modal=o.dataset.open;render();return}
  const accountTx=e.target.closest("[data-open-account-tx]");if(accountTx){state.pendingAccount=accountTx.dataset.openAccountTx;modal="transaction";render();return}
  if(e.target.closest("[data-close-modal]")&&(!e.target.closest(".modal")||e.target.closest("button[data-close-modal]"))){modal=null;editingPathId=null;editingGoalId=null;editingSubscriptionId=null;render();return}
  const mode=e.target.closest("button[data-mode]");if(mode){state.profile.mode=mode.dataset.mode;view="dashboard";save();render();return}
  const themeBtn=e.target.closest("button[data-theme]");if(themeBtn){state.profile.theme=themeBtn.dataset.theme;save();render();return}
  const accent=e.target.closest("button[data-accent]");if(accent){state.profile.accent=accent.dataset.accent;save();render();return}
  const density=e.target.closest("button[data-density]");if(density){state.profile.density=Number(density.dataset.density);save();render();return}
  const choice=e.target.closest("button[data-choice]");if(choice){document.querySelectorAll("button[data-choice]").forEach(x=>x.classList.remove("active"));choice.classList.add("active");document.querySelector('[name="mode"]').value=choice.dataset.choice;return}
  const del=e.target.closest("[data-delete-tx]");if(del){const tx=state.transactions.find(x=>x.id===del.dataset.deleteTx),account=tx&&state.accounts.find(x=>x.id===tx.accountId);if(account&&!tx.reviewed&&tx.type!=="transfer")account.balance=Number(account.balance||0)+(tx.type==="income"?-Number(tx.amount||0):Number(tx.amount||0));state.transactions=state.transactions.filter(x=>x.id!==del.dataset.deleteTx);save();render();toast(tx?.reviewed?"Reviewed transaction removed":"Transaction removed and balance restored");return}
  const editReview=e.target.closest("[data-edit-review]");if(editReview){reviewingId=editReview.dataset.editReview;modal="review";render();return}
  const approveReview=e.target.closest("[data-approve-review]");if(approveReview){const item=state.reviewQueue.find(x=>x.id===approveReview.dataset.approveReview);if(item){const account=state.accounts.find(x=>x.id===item.accountId),type=reviewTypeToLedger(item.suggestedType);state.transactions.unshift({id:uid("tx"),date:item.date,name:item.name,category:item.suggestedCategory,account:account?.name||"Imported",accountId:item.accountId,type,amount:item.amount,note:item.note,reviewed:true});if(item.suggestedType==="loan-given")state.loansGiven.push({id:uid("given"),name:item.name,borrower:"Needs detail",balance:item.amount,original:item.amount,rate:0,payment:0,due:"Pending"});state.reviewQueue=state.reviewQueue.filter(x=>x.id!==item.id);save();render();toast(type==="transfer"?"Seen as neutral transfer":"Seen and moved to Transactions")}return}
  const delAccount=e.target.closest("[data-delete-account]");if(delAccount){if(state.accounts.length===1)return toast("Keep at least one account");state.accounts=state.accounts.filter(x=>x.id!==delAccount.dataset.deleteAccount);save();render();toast("Account removed");return}
  const contribute=e.target.closest("[data-contribute-goal]");if(contribute){const goal=state.goals.find(x=>x.id===contribute.dataset.contributeGoal),account=state.accounts[0];if(goal&&account){const currency=goalCurrency(goal),gap=Math.max(0,goal.target-goal.saved),suggestedAccount=Math.max(convertMoney(100,currency,state.profile.currency),totals().cashflow*.25),goalAmount=Math.min(gap,convertMoney(suggestedAccount,state.profile.currency,currency)),accountAmount=convertMoney(goalAmount,currency,state.profile.currency);if(!goalAmount)return toast("This goal is already fully secured");if(account.balance<accountAmount)return toast("The selected cash account cannot cover this contribution");goal.saved+=goalAmount;account.balance-=accountAmount;save();render();toast(`${moneyIn(goalAmount,currency)} moved toward ${goal.name}`)}return}
  const editGoal=e.target.closest("[data-edit-goal]");if(editGoal){const goal=state.goals.find(x=>x.id===editGoal.dataset.editGoal);if(!goal)return toast("Goal not found");if(goalEditsLeft(goal)<=0)return toast("This goal has used all available edits");editingGoalId=goal.id;modal="goal";render();return}
  const primary=e.target.closest("[data-primary-goal]");if(primary){state.goals.forEach(g=>g.priority=g.id===primary.dataset.primaryGoal?1:Math.max(2,Number(g.priority)||2));save();render();toast("Primary goal updated");return}
  const delGoal=e.target.closest("[data-delete-goal]");if(delGoal){state.goals=state.goals.filter(x=>x.id!==delGoal.dataset.deleteGoal);save();render();toast("Goal removed");return}
  const editPath=e.target.closest("[data-edit-path]");if(editPath){editingPathId=editPath.dataset.editPath;modal="incomePath";render();return}
  const logSale=e.target.closest("[data-log-path-sale]");if(logSale){const path=state.incomePaths.find(x=>x.id===logSale.dataset.logPathSale);if(path){path.sold=Math.max(0,Number(path.sold)||0)+1;path.plannedSales=Math.max(Number(path.plannedSales)||0,path.sold);save();render();toast(`One ${path.name} sale logged`)}return}
  const delPath=e.target.closest("[data-delete-path]");if(delPath){const path=state.incomePaths.find(x=>x.id===delPath.dataset.deletePath);if(path&&confirm(`Remove ${path.name} from this goal plan?`)){state.incomePaths=state.incomePaths.filter(x=>x.id!==path.id);save();render();toast("Income path removed")}return}
  const pos=e.target.closest("[data-delete-position]");if(pos){const[k,id]=pos.dataset.deletePosition.split("|");state[k==="asset"?"assets":"liabilities"]=state[k==="asset"?"assets":"liabilities"].filter(x=>x.id!==id);save();render();return}
  const pay=e.target.closest("[data-pay-loan]");if(pay){const loan=state.loans.find(x=>x.id===pay.dataset.payLoan);if(loan){loan.balance=Math.max(0,loan.balance-loan.payment);const liability=state.liabilities.find(x=>x.name===loan.name);if(liability)liability.value=loan.balance;save();render();toast("Payment recorded and net worth updated")}return}
  const collect=e.target.closest("[data-collect-loan]");if(collect){const loan=state.loansGiven.find(x=>x.id===collect.dataset.collectLoan);if(loan){loan.balance=Math.max(0,Number(loan.balance||0)-Number(loan.payment||0));const account=state.accounts[0];if(account)account.balance=Number(account.balance||0)+Number(loan.payment||0);save();render();toast("Collection recorded and account balance updated")}return}
  const editSub=e.target.closest("[data-edit-sub]");if(editSub){editingSubscriptionId=editSub.dataset.editSub;modal="subscription";render();return}
  const sub=e.target.closest("[data-toggle-sub]");if(sub){const x=state.subscriptions.find(y=>y.id===sub.dataset.toggleSub);x.active=!x.active;save();render();return}
  const action=e.target.closest("[data-action]")?.dataset.action;if(action==="privacy"){state.profile.privacy=!state.profile.privacy;save();render()}if(action==="tutorial"){tutorialStep=0;state.profile.tutorialDone=false;save();render()}if(action==="export")exportData();if(action==="import")importFile.click();if(action==="logout"){authenticated=false;sessionStorage.removeItem("finmax_session");sessionStorage.removeItem("finmax_user_id");authMode="login";render()}if(action==="reset"){if(confirm("Reset all offline finance data to the imported statement baseline?")){state=structuredClone(seed);authenticated=false;sessionStorage.removeItem("finmax_session");sessionStorage.removeItem("finmax_user_id");save();view="dashboard";render()}}
});

document.addEventListener("input",e=>{if(e.target.matches("[data-password-watch]")){const form=e.target.closest("form"),rules=form?.querySelector("[data-password-rules]"),password=form?.querySelector('[name="password"]')?.value||"",confirm=form?.querySelector('[name="confirm"]')?.value||"";if(rules)rules.innerHTML=passwordRules(password,confirm).map(rule=>`<span data-rule="${rule.key}" class="${rule.ok?"ok":""}">${rule.ok?"✓":"•"} ${rule.label}</span>`).join("");return}if(e.target.matches("[data-search]")){search=e.target.value;const caret=e.target.selectionStart;render();const next=document.querySelector("[data-search]");next.focus();next.setSelectionRange(caret,caret)}});
document.addEventListener("change",e=>{const config=e.target.closest("[data-goal-config]");if(config){const key=config.dataset.goalConfig,min=key==="fxUsdNgn"?1:1,max=key==="goalHoursWeek"?168:Infinity;state.profile[key]=Math.min(max,Math.max(min,Number(config.value)||min));config.value=state.profile[key];save();render();toast(key==="fxUsdNgn"?"Offline exchange rate updated":"Weekly capacity updated");return}const field=e.target.closest("[data-profile-number]");if(!field)return;const minimum=field.dataset.profileNumber==="monthlyBudget"?1:0;state.profile[field.dataset.profileNumber]=Math.max(minimum,Number(field.value)||minimum);field.value=state.profile[field.dataset.profileNumber];save();toast("FinMax guidance updated")});
document.addEventListener("submit",e=>{const form=e.target;if(form.dataset.form!=="goal")return;const data=Object.fromEntries(new FormData(form)),id=String(data.id||""),existing=id&&state.goals.find(g=>g.id===id);if(existing){if(goalEditsLeft(existing)<=0){form.dataset.form="goal-blocked";toast("This goal has used all available edits");return}Object.assign(existing,{name:data.name,type:data.type,currency:data.currency,target:Number(data.target),saved:Number(data.saved||0),due:data.due,priority:Number(data.priority),editsUsed:(Number(existing.editsUsed)||0)+1,lastEditedAt:new Date().toISOString()});if(existing.priority===1)state.goals.forEach(g=>{if(g.id!==existing.id)g.priority=Math.max(2,Number(g.priority)||2)});editingGoalId=null;form.dataset.form="goal-saved";return}const goal={id:uid("goal"),name:data.name,type:data.type,currency:data.currency,target:Number(data.target),saved:Number(data.saved||0),due:data.due,priority:Number(data.priority),editsUsed:0,editLimit:MAX_GOAL_EDITS,createdAt:new Date().toISOString()};if(goal.priority===1){state.goals.forEach(g=>g.priority=Math.max(2,Number(g.priority)||2));state.goals.unshift(goal)}else state.goals.push(goal);form.dataset.form="goal-saved"},{capture:true});
document.addEventListener("submit",e=>{if(e.target.dataset.form!=="goal-blocked")return;e.preventDefault();e.stopImmediatePropagation()},{capture:true});
document.addEventListener("submit",e=>{const form=e.target;if(form.dataset.form!=="loan")return;const data=Object.fromEntries(new FormData(form));if(data.direction==="lent"){state.loansGiven.push({id:uid("given"),name:data.name,borrower:data.party,balance:Number(data.balance),original:Number(data.original),rate:Number(data.rate),payment:Number(data.payment),due:"Next cycle"});form.dataset.form="loan-given"}else{const hidden=document.createElement("input");hidden.type="hidden";hidden.name="lender";hidden.value=data.party;form.append(hidden)}},{capture:true});
document.addEventListener("submit",e=>{const form=e.target;if(form.dataset.form!=="subscription")return;const data=Object.fromEntries(new FormData(form)),existing=data.id&&state.subscriptions.find(x=>x.id===data.id);if(!existing)return;Object.assign(existing,{name:data.name.trim(),amount:Number(data.amount),category:data.category.trim()||"Other",cycle:data.cycle,next:data.next||"Next cycle"});editingSubscriptionId=null;form.dataset.form="subscription-saved"},{capture:true});
document.addEventListener("submit",async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));if(form.dataset.form==="onboard"){state.profile.name=data.name.trim();state.profile.currency=data.currency;state.profile.mode=data.mode;state.profile.onboarded=true;state.profile.tutorialDone=false;save();authMode=db.users.length?"login":"signup";localStorage.setItem("finmax_auth_mode",authMode);render();return}if(form.dataset.form==="signup"){const username=data.username.trim().toLowerCase(),password=String(data.password||""),rules=passwordRules(password,String(data.confirm||""));if(!username)return toast("Choose a username");if(db.users.some(x=>x.username===username))return toast("That username already exists");if(rules.some(x=>!x.ok))return toast("Password must satisfy every rule");db.users.push({id:uid("user"),username,displayName:data.displayName.trim(),passwordHash:await hashPassword(password),createdAt:new Date().toISOString()});saveUserDb();state.profile.name=data.displayName.trim();state.profile.username=username;save();authMode="login";localStorage.setItem("finmax_auth_mode","login");render();toast("Account created. Login to continue.");return}if(form.dataset.form==="login"){const username=data.username.trim().toLowerCase(),user=db.users.find(x=>x.username===username),hash=await hashPassword(data.password);if(!user||user.passwordHash!==hash)return toast("Username or password is incorrect");authenticated=true;sessionStorage.setItem("finmax_session","yes");sessionStorage.setItem("finmax_user_id",user.id);state.profile.name=user.displayName||state.profile.name;state.profile.username=user.username;save();render();toast("FinMax unlocked");return}if(form.dataset.form==="review"){const item=state.reviewQueue.find(x=>x.id===data.id),account=state.accounts.find(x=>x.id===data.accountId);if(!item||!account)return toast("Review item no longer exists");const type=reviewTypeToLedger(data.type);state.transactions.unshift({id:uid("tx"),date:data.date,name:data.name.trim(),category:data.category,account:account.name,accountId:account.id,type,amount:Number(data.amount),note:data.note,reviewed:true});if(data.type==="loan-given")state.loansGiven.push({id:uid("given"),name:data.name.trim(),borrower:"Needs detail",balance:Number(data.amount),original:Number(data.amount),rate:0,payment:0,due:"Pending"});state.reviewQueue=state.reviewQueue.filter(x=>x.id!==item.id);reviewingId=null;modal=null;save();render();toast(type==="transfer"?"Neutral transfer approved":"Imported item approved");return}if(form.dataset.form==="transaction"){const account=state.accounts.find(x=>x.id===data.accountId),amount=Number(data.amount);if(!account)return toast("Choose a valid account");account.balance=Number(account.balance||0)+(data.type==="income"?amount:-amount);state.transactions.unshift({id:uid("tx"),name:data.name,amount,type:data.type,category:data.category,account:account.name,accountId:account.id,date:data.date});delete state.pendingAccount;}if(form.dataset.form==="account"){state.accounts.push({id:uid("account"),name:data.name,institution:data.institution,kind:data.kind,type:data.type,balance:Number(data.balance),color:data.color});}if(form.dataset.form==="income-path"){const payload={id:data.id||uid("path"),name:data.name.trim(),currency:data.currency,offer:Number(data.offer),plannedSales:Number(data.plannedSales),sold:Number(data.sold),hoursPerSale:Number(data.hoursPerSale),monthlyCapacity:Number(data.monthlyCapacity),status:data.status},index=state.incomePaths.findIndex(x=>x.id===payload.id);if(payload.sold>payload.plannedSales)return toast("Sales already won cannot exceed planned sales");if(index>=0)state.incomePaths[index]=payload;else state.incomePaths.push(payload);editingPathId=null;}if(form.dataset.form==="position"){const list=form.dataset.kind==="asset"?state.assets:state.liabilities;list.push({id:uid(form.dataset.kind),name:data.name,type:data.type,value:Number(data.value)});}if(form.dataset.form==="loan"){state.loans.push({id:uid("loan"),name:data.name,lender:data.lender,balance:Number(data.balance),original:Number(data.original),rate:Number(data.rate),payment:Number(data.payment),due:"Next cycle"});state.liabilities.push({id:uid("liability"),name:data.name,type:"Loan",value:Number(data.balance)});}if(form.dataset.form==="subscription"){state.subscriptions.push({id:uid("sub"),name:data.name,amount:Number(data.amount),category:data.category,cycle:data.cycle,next:data.next||"Next cycle",active:true});}save();modal=null;render();toast("Saved offline");});
importFile.addEventListener("change",async()=>{const file=importFile.files[0];if(!file)return;try{state=merge(structuredClone(seed),JSON.parse(await file.text()));save();render();toast("Backup restored")}catch{toast("That backup could not be read")}importFile.value=""});
function goalCard(g,primaryGoal){const pct=Math.round((Number(g.saved)||0)/(Number(g.target)||1)*100),left=goalEditsLeft(g),limit=goalEditLimit(g);return `<article class="card goal-card"><div class="card-head"><div><span class="eyebrow">Priority ${g.priority} · ${esc(g.type)} · ${goalCurrency(g)}</span><h2>${esc(g.name)}</h2></div><span class="badge ${g.id===primaryGoal.id?"active":""}">${pct}%</span></div>${goalProgress(g)}<div class="goal-edit-note">${left} of ${limit} edits left</div><div class="goal-actions"><button class="btn" data-edit-goal="${g.id}" ${left<=0?"disabled":""}>Edit goal</button><button class="btn" data-primary-goal="${g.id}">${g.id===primaryGoal.id?"Primary goal":"Make primary"}</button><button class="btn primary" data-contribute-goal="${g.id}">Add contribution</button><button class="btn danger" data-delete-goal="${g.id}">Remove</button></div></article>`}
function goals(){const goal=activeGoal(),actions=`<div class="goal-page-actions"><button class="btn" data-open="incomePath">+ Income path</button><button class="btn primary" data-open="goal">+ Financial goal</button></div>`;if(!goal)return `${pageHead("Goals","Build a measurable route from today to the number that matters.",actions)}<article class="card empty-goal"><span class="eyebrow">Start here</span><h2>Create your first financial goal</h2><p>Choose a currency and deadline. FinMax will calculate the pace required without sending anything online.</p><button class="btn primary" data-open="goal">Create goal</button></article>`;const currency=goalCurrency(goal),plan=goalPlan(goal),secured=Number(goal.saved)||0,pct=Math.min(100,Math.round(secured/(Number(goal.target)||1)*100)),weekly=plan.gap/plan.weeks,other=currency==="USD"?"NGN":"USD",converted=convertMoney(goal.target,currency,other),capacityOver=plan.hours>plan.availableHours,covered=plan.forecastGap<=0;return `${pageHead("Goal Lab","One target, multiple editable routes, and no hidden arithmetic.",actions)}<section class="goal-command"><div class="goal-command-main"><div class="goal-command-top"><div><span class="eyebrow">Primary goal · ${esc(goal.type)} · ${currency}</span><h2>${esc(goal.name)}</h2></div><span class="goal-deadline">${plan.days} days left</span></div><div class="goal-total privacy-amount" data-hidden="${state.profile.privacy}"><strong>${moneyIn(secured,currency)}</strong><span>/ ${moneyIn(goal.target,currency)}</span></div><div class="progress goal-master-progress"><span style="--value:${pct}%"></span></div><div class="goal-command-meta"><span>${pct}% secured</span><span>Target equals ${moneyIn(converted,other,true)} at your current rate</span></div></div><aside class="goal-pace"><span class="eyebrow">Required pace from here</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(weekly,currency,true)}</strong><span>per week</span><small>Sales won reduce the remaining pace even before cash is assigned.</small></aside></section><section class="goal-settings-bar"><label><span>Offline exchange rate</span><div class="inline-rate"><b>1 USD =</b><input type="number" min="1" step="1" value="${state.profile.fxUsdNgn}" data-goal-config="fxUsdNgn"><b>NGN</b></div></label><label><span>Time available around school</span><div class="inline-rate"><input type="number" min="1" max="168" step="1" value="${state.profile.goalHoursWeek}" data-goal-config="goalHoursWeek"><b>hours / week</b></div></label><p>Both values stay on this device. Update the rate whenever you choose.</p></section><div class="grid goal-kpis"><article><span>Income already won</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(plan.confirmed,currency,true)}</strong><small>From logged path sales</small></article><article><span>Planned path value</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(plan.forecast,currency,true)}</strong><small>${plan.coverage}% total goal coverage</small></article><article><span>Work required</span><strong>${Math.round(plan.hours)}h</strong><small>of ${Math.round(plan.availableHours)}h available</small></article><article class="${covered&&!capacityOver?"plan-good":"plan-watch"}"><span>Plan signal</span><strong>${!covered?"Revenue gap":capacityOver?"Over capacity":"Covered"}</strong><small>${!covered?`${moneyIn(plan.forecastGap,currency,true)} still unassigned`:capacityOver?`${Math.round(plan.hours-plan.availableHours)}h beyond your limit`:"The route works on paper"}</small></article></div><div class="section-title goal-section-title"><div><span class="eyebrow">Income architecture</span><h2>Your routes to the goal</h2></div><span class="muted">Add, edit, remove, or log one sale</span></div><div class="grid three-col income-path-grid">${state.incomePaths.map(path=>incomePathCard(path,goal)).join("")||`<article class="card empty-goal"><h3>No income paths yet</h3><p>Add the offers or products you are building.</p><button class="btn primary" data-open="incomePath">Add income path</button></article>`}</div><div class="section-title goal-section-title"><div><span class="eyebrow">Goal portfolio</span><h2>All financial goals</h2></div></div><div class="grid two-col">${[...state.goals].sort((a,b)=>(a.priority||9)-(b.priority||9)).map(g=>goalCard(g,goal)).join("")}</div>`}
function goalForm(){const goal=state.goals.find(x=>x.id===editingGoalId),editing=Boolean(goal),left=editing?goalEditsLeft(goal):MAX_GOAL_EDITS,type=goal?.type||"Growth",currency=goal?.currency||state.profile.currency,priority=String(goal?.priority||2);return `${modalHeader(editing?"Edit financial goal":"Create financial goal",editing?`${left} ${left===1?"edit":"edits"} left after this goal was created.`:"FinMax will calculate the pace and compare it with your income paths.")}<form data-form="goal"><input name="id" value="${esc(goal?.id||"")}" hidden><div class="form-grid"><div class="field full"><label>Goal name</label><input name="name" required value="${esc(goal?.name||"")}" placeholder="$1M, emergency reserve, home deposit..."></div><div class="field"><label>Goal type</label><select name="type">${["Business","Growth","Safety","Debt","Purchase"].map(x=>`<option ${type===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Goal currency</label><select name="currency">${["USD","NGN"].map(x=>`<option ${currency===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label>Priority</label><select name="priority">${[[1,"High"],[2,"Medium"],[3,"Low"]].map(([value,label])=>`<option value="${value}" ${priority===String(value)?"selected":""}>${label}</option>`).join("")}</select></div><div class="field"><label>Target amount</label><input name="target" type="number" min="1" step="0.01" required value="${goal?.target??""}"></div><div class="field"><label>Already secured</label><input name="saved" type="number" min="0" step="0.01" value="${goal?.saved??0}"></div><div class="field full"><label>Exact target date</label><input name="due" type="date" required value="${esc(goal?.due||"")}"></div></div>${editing?`<p class="goal-edit-warning">${left>0?`Saving this change will use 1 edit. ${Math.max(0,left-1)} will remain.`:"This goal has no edits left."}</p>`:""}${modalActions()}</form>`}
function review(){const items=state.reviewQueue||[],summary=globalThis.FINMAX_PRIVATE_REVIEW_DATA?.summary||[];return `${pageHead("Transaction Review","Every imported statement line waits here until you update it or mark it Seen.",`<button class="btn primary" data-open="transaction">Log manual item</button>`)}<div class="review-summary-bar"><strong>${items.length} pending</strong><span>${state.transactions.length} approved ledger entries</span>${summary.map(x=>`<span>${esc(x.file.replace(/\\.pdf$/,""))}: ${x.rows}</span>`).join("")}</div><div class="grid review-layout"><article class="card card-pad review-queue-card"><div class="card-head"><div><h3>Review queue</h3><span class="muted">Flat rows stay compact; Update opens the full editor.</span></div><span class="badge ${items.length?"":"active"}">${items.length?"Needs review":"Clear"}</span></div><div class="review-list compact">${items.map(reviewRow).join("")||`<div class="empty-review"><strong>All clear.</strong><p class="muted">New ambiguous imports will appear here first, then move to Transactions after approval.</p></div>`}</div></article><aside class="grid"><article class="card card-pad"><span class="eyebrow">Rule of the app</span><h3>No imported line is trusted automatically.</h3><p class="muted">Savings deposits, POS cash, loans, pass-through transfers, fees, and subscriptions only affect the ledger after you confirm their meaning.</p></article><article class="card card-pad"><h3>Fast classification</h3><div class="truth-list"><p><strong>Seen</strong><span>approve suggested meaning</span></p><p><strong>Update</strong><span>edit description, category, account, or type</span></p><p><strong>Transfer</strong><span>neutral movement, not spending</span></p></div></article></aside></div>`}
function reviewRow(x){const account=state.accounts.find(a=>a.id===x.accountId);return `<div class="review-item"><div class="review-main"><span class="eyebrow">${esc(x.date)} · ${esc(account?.name||"Unassigned")} · ${esc(x.source||"Import")}</span><h3>${esc(x.name)}</h3><small>${esc(x.suggestedType)} · ${esc(x.suggestedCategory)}</small></div><strong class="review-amount">${money(x.amount)}</strong><div class="review-actions"><button class="btn small" data-edit-review="${x.id}">Update</button><button class="btn small primary" data-approve-review="${x.id}">Seen</button></div></div>`}
function accountGroup(title,items,open=true){return `<details class="account-group" ${open?"open":""}><summary><span>${esc(title)}</span><strong>${money(sum(items,"balance"))}</strong><small>${items.length} ${items.length===1?"account":"accounts"}</small></summary><div class="grid three-col">${items.map(x=>`<article class="card account-card"><div class="account-color" style="background:${x.color}"></div><div class="loan-top"><div><span class="eyebrow">${esc(x.institution)}</span><h3>${esc(x.name)}</h3></div><span class="badge ${x.kind==="Business"?"active":""}">${esc(x.type)}</span></div><div class="account-balance privacy-amount" data-hidden="${state.profile.privacy}">${money(x.balance)}</div><div class="account-actions"><button class="btn small" data-open-account-tx="${x.id}">Add activity</button><button class="btn small danger" data-delete-account="${x.id}">Remove</button></div></article>`).join("")}</div></details>`}
function accounts(){const groups=["Personal","Business","Savings","Investment"].map(kind=>[kind,state.accounts.filter(x=>x.kind===kind)]),other=state.accounts.filter(x=>!["Personal","Business","Savings","Investment"].includes(x.kind));return `${pageHead("Accounts","Balances are grouped and collapsible so the page stays neat.",`<button class="btn primary" data-open="account">+ Add account</button>`)}<div class="grid kpi-grid">${kpi("All account balances",sum(state.accounts,"balance"),`${state.accounts.length} offline accounts`)}${kpi("Personal",sum(state.accounts.filter(x=>x.kind==="Personal"),"balance"),"daily money")}${kpi("Business",sum(state.accounts.filter(x=>x.kind==="Business"),"balance"),"Dominique Creations")}${kpi("Savings and investments",sum(state.accounts.filter(x=>["Savings","Investment"].includes(x.kind)),"balance"),"protected buckets")}</div><div class="account-groups">${groups.filter(([,items])=>items.length).map(([name,items],i)=>accountGroup(name,items,i<2)).join("")}${other.length?accountGroup("Other",other,false):""}</div>`}
function subscriptions(){const active=state.subscriptions.filter(x=>x.active),monthly=active.reduce((n,x)=>n+x.amount/(x.cycle==="Yearly"?12:1),0);return `${pageHead("Subscriptions","Recurring costs you can edit when details are wrong.",`<button class="btn" data-open="subscription">+ Add subscription</button>`)}<div class="grid kpi-grid">${kpi("Monthly total",monthly,"Normalized recurring cost")}${kpi("Annual run rate",monthly*12,"If nothing changes")}${kpi("Active services",String(active.length),`${state.subscriptions.length-active.length} paused`)}${kpi("Largest recurring",Math.max(0,...active.map(x=>x.amount)),"Current billing amount")}</div><div class="grid three-col">${state.subscriptions.map(x=>`<article class="card sub-card ${x.active?"":"inactive"}"><div class="sub-top"><span class="sub-logo">${esc(x.name[0])}</span><div class="sub-actions"><button class="btn small" data-edit-sub="${x.id}">Edit</button><button class="btn small" data-toggle-sub="${x.id}">${x.active?"Pause":"Resume"}</button></div></div><div><h3>${esc(x.name)}</h3><span class="muted">${esc(x.category)}</span></div><div class="loan-top"><strong>${money(x.amount)} / ${x.cycle==="Yearly"?"yr":"mo"}</strong><small>Next ${esc(x.next)}</small></div></article>`).join("")}</div>`}
function subscriptionForm(){const sub=state.subscriptions.find(x=>x.id===editingSubscriptionId),editing=Boolean(sub),cycle=sub?.cycle||"Monthly";return `${modalHeader(editing?"Edit subscription":"Add subscription",editing?"Correct the amount, category, billing cycle, or next billing note.":"Make the next recurring charge visible.")}<form data-form="subscription"><input name="id" value="${esc(sub?.id||"")}" hidden><div class="form-grid"><div class="field full"><label>Service</label><input name="name" required value="${esc(sub?.name||"")}"></div><div class="field"><label>Amount</label><input name="amount" type="number" min="0" step="0.01" required value="${sub?.amount??""}"></div><div class="field"><label>Category</label><input name="category" value="${esc(sub?.category||"Other")}"></div><div class="field"><label>Cycle</label><select name="cycle">${["Monthly","Yearly"].map(x=>`<option ${cycle===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field full"><label>Next billing</label><input name="next" value="${esc(sub?.next||"")}" placeholder="Jul 15 or Paused"></div></div>${modalActions()}</form>`}
function goalCheckpoints(goal){const target=Number(goal.target)||0,currency=goalCurrency(goal);let points=currency==="USD"&&target>=1000000?[5000,10000,100000,250000,500000,750000,target]:[.05,.1,.25,.5,.75,1].map(p=>Math.round(target*p));return [...new Set(points.filter(x=>x>0&&x<=target))].sort((a,b)=>a-b)}
function checkpointState(goal){const saved=Number(goal.saved)||0,points=goalCheckpoints(goal),last=[...points].reverse().find(x=>saved>=x)||0,next=points.find(x=>saved<x)||points[points.length-1]||Number(goal.target)||0;return{points,last,next}}
function goalCheckpointStrip(goal,full=false){const currency=goalCurrency(goal),stateCp=checkpointState(goal),saved=Number(goal.saved)||0,points=goalCheckpoints(goal);return `<div class="checkpoint-card ${full?"full":""}"><div class="checkpoint-copy"><span class="eyebrow">Checkpoints</span><strong>${stateCp.last?`Reached ${moneyIn(stateCp.last,currency,true)}`:"First checkpoint pending"}</strong><small>Next: ${moneyIn(stateCp.next,currency,true)}</small></div><div class="checkpoint-track">${points.map(p=>`<span class="${saved>=p?"hit":p===stateCp.next?"next":""}" title="${moneyIn(p,currency)}"></span>`).join("")}</div>${full?`<div class="checkpoint-labels">${points.map(p=>`<small class="${saved>=p?"hit":""}">${moneyIn(p,currency,true)}</small>`).join("")}</div>`:""}</div>`}
function goalProgressBase(goal){const currency=goalCurrency(goal),pct=Math.min(100,Math.round((Number(goal.saved)||0)/(Number(goal.target)||1)*100));return `<div class="goal-amount privacy-amount" data-hidden="${state.profile.privacy}"><strong>${moneyIn(goal.saved,currency)}</strong><span>of ${moneyIn(goal.target,currency)}</span></div><div class="progress"><span style="--value:${pct}%"></span></div><div class="loan-top"><small class="muted">${pct}% secured</small><small>Due ${esc(goal.due)}</small></div>`}
function goalProgress(goal){return `${goalProgressBase(goal)}${goalCheckpointStrip(goal,false)}`}
function goalCard(g,primaryGoal){const pct=Math.round((Number(g.saved)||0)/(Number(g.target)||1)*100),left=goalEditsLeft(g),limit=goalEditLimit(g);return `<article class="card goal-card"><div class="card-head"><div><span class="eyebrow">Priority ${g.priority} · ${esc(g.type)} · ${goalCurrency(g)}</span><h2>${esc(g.name)}</h2></div><span class="badge ${g.id===primaryGoal.id?"active":""}">${pct}%</span></div>${goalProgressBase(g)}${goalCheckpointStrip(g,true)}<div class="goal-edit-note">${left} of ${limit} edits left</div><div class="goal-actions"><button class="btn" data-edit-goal="${g.id}" ${left<=0?"disabled":""}>Edit goal</button><button class="btn" data-primary-goal="${g.id}">${g.id===primaryGoal.id?"Primary goal":"Make primary"}</button><button class="btn primary" data-contribute-goal="${g.id}">Add contribution</button><button class="btn danger" data-delete-goal="${g.id}">Remove</button></div></article>`}
function rankDashboard(){const t=totals(),m=movementTotals(),goal=activeGoal(),reviewTotal=state.transactions.length+(state.reviewQueue||[]).length,reviewedRatio=reviewTotal?state.transactions.length/reviewTotal:1,baseAwareness=Math.min(900,reviewTotal*.42),reviewXp=state.transactions.length*5,goalXp=goal?convertMoney(Number(goal.saved)||0,goalCurrency(goal),state.profile.currency)*.002:0,xp=Math.max(0,Math.round(baseAwareness+reviewXp+(m.income*.006)+(m.protectedSavings*.01)+goalXp-(m.spending*.002))),rank=xp>8000?"A":xp>5000?"B":xp>2500?"C":xp>1000?"D":"E",next={E:1000,D:2500,C:5000,B:8000,A:12000}[rank]||12000,pct=Math.min(100,Math.round(xp/next*100)),savingRate=m.income?Math.round(m.protectedSavings/m.income*100):0;return `${pageHead(`Rank Mode, ${esc(state.profile.name)}`,"Review imports, protect savings, and turn money clarity into progress.",`<button class="btn primary" data-view="review">Open review queue</button>`)}<section class="rank-hero card"><div><span class="eyebrow">Financial Rank</span><h2>${rank} Rank</h2><p>${m.reviewCount?`${m.reviewCount} imported items still need judgement. FinMax gives some awareness XP, but the real rank jump comes from classifying them.`:"Your transaction queue is clear. Keep logging and protecting savings."}</p></div><div class="rank-orb"><strong>${rank}</strong><span>${xp} XP</span></div></section><div class="grid kpi-grid rank-kpis">${kpi("Reviewed logs",state.transactions.length,`${Math.round(reviewedRatio*100)}% of imported truth`,"positive")}${kpi("Pending review",m.reviewCount,"needs classification",m.reviewCount?"negative":"positive")}${kpi("Protected savings",m.protectedSavings,"not counted as spending","positive")}${kpi("Saving shield",`${savingRate}%`,"protected out of income",savingRate>=20?"positive":"")}</div><div class="grid dash-grid"><article class="card card-pad"><div class="card-head"><div><h3>Rank progress</h3><span class="muted">${xp} / ${next} XP toward the next bracket</span></div><span class="badge active">Balanced XP</span></div><div class="rank-track"><span style="--value:${pct}%"></span></div><div class="rank-missions"><button class="btn" data-view="review">Classify imports</button><button class="btn" data-open="transaction">Log new activity</button><button class="btn primary" data-view="goals">Push main goal</button></div></article><aside class="grid"><article class="card card-pad"><div class="card-head"><h3>Operating truth</h3><span class="badge">No shame math</span></div><div class="truth-list"><p><strong>${money(m.grossOutflow,true)}</strong><span>approved gross outflow</span></p><p><strong>${money(m.protectedSavings,true)}</strong><span>saved or protected movement</span></p><p><strong>${money(m.spending,true)}</strong><span>actual spend pressure estimate</span></p></div></article><article class="card card-pad"><h3>Primary objective</h3>${goal?goalProgress(goal):`<p class="muted">Create a goal to connect Rank Mode with a target.</p>`}</article></aside></div>`}
const reviewFilters={query:"",source:"all",account:"all",type:"all",sort:"statement",limit:120};
const txFilters={query:"",account:"all",category:"all",type:"all",source:"all",sort:"date-desc"};

function optionList(options,value){return options.map(([val,label])=>`<option value="${esc(val)}" ${String(value)===String(val)?"selected":""}>${esc(label)}</option>`).join("")}
function filterSelect(scope,key,label,value,options){return `<label class="filter-field"><span>${esc(label)}</span><select data-filter-scope="${scope}" data-filter-key="${key}">${optionList(options,value)}</select></label>`}
function filterInput(scope,key,label,value,placeholder){return `<label class="filter-field filter-search"><span>${esc(label)}</span><input value="${esc(value)}" placeholder="${esc(placeholder)}" data-filter-scope="${scope}" data-filter-key="${key}"></label>`}
function uniqueValues(items,fn){return [...new Set(items.map(fn).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b)))}
function compareDate(a,b){return (Date.parse(a?.date)||0)-(Date.parse(b?.date)||0)}
function compareText(a,b,fn){return String(fn(a)||"").localeCompare(String(fn(b)||""))}
function privateSourceMap(){const data=globalThis.FINMAX_PRIVATE_REVIEW_DATA;if(!data?.rows||!data?.summary)return{};if(privateSourceMap.cache)return privateSourceMap.cache;const counts={};data.rows.forEach(row=>{const key=row.source||"Imported statement";counts[key]=(counts[key]||0)+1});privateSourceMap.cache=Object.fromEntries(Object.entries(counts).map(([source,count])=>{const matches=data.summary.filter(item=>Number(item.rows)===count);return[source,matches.length===1?matches[0].file:source]}));return privateSourceMap.cache}
function reviewPdfLabel(item){if(item?.sourceFile)return item.sourceFile;if(item?.file)return item.file;const source=item?.source||"Imported statement";return privateSourceMap()[source]||source}
function shortPdfLabel(label){return String(label||"Imported statement").replace(/\.pdf$/i,"").replace(/^Statements download_/i,"PalmPay ").replace(/^Moniepoint-Document-/i,"Moniepoint ")}
function reviewIndexMap(){const rows=globalThis.FINMAX_PRIVATE_REVIEW_DATA?.rows;if(!Array.isArray(rows))return new Map();if(reviewIndexMap.cache)return reviewIndexMap.cache;reviewIndexMap.cache=new Map(rows.map((row,index)=>[row.id,index]));return reviewIndexMap.cache}
function sortedReviewItems(items){const list=[...items];const sort=reviewFilters.sort;if(sort==="date-desc")list.sort((a,b)=>compareDate(b,a));else if(sort==="date-asc")list.sort(compareDate);else if(sort==="amount-desc")list.sort((a,b)=>Number(b.amount||0)-Number(a.amount||0));else if(sort==="amount-asc")list.sort((a,b)=>Number(a.amount||0)-Number(b.amount||0));else if(sort==="source")list.sort((a,b)=>compareText(a,b,reviewPdfLabel)||compareDate(b,a));else list.sort((a,b)=>(reviewIndexMap().get(a.id)??0)-(reviewIndexMap().get(b.id)??0));return list}
function filteredReviewItems(){const q=reviewFilters.query.trim().toLowerCase();return sortedReviewItems((state.reviewQueue||[]).filter(item=>{const pdf=reviewPdfLabel(item),account=state.accounts.find(x=>x.id===item.accountId);if(reviewFilters.source!=="all"&&pdf!==reviewFilters.source)return false;if(reviewFilters.account!=="all"&&item.accountId!==reviewFilters.account)return false;if(reviewFilters.type!=="all"&&item.suggestedType!==reviewFilters.type)return false;if(!q)return true;return`${item.name} ${item.suggestedCategory} ${item.suggestedType} ${item.date} ${item.amount} ${item.note||""} ${pdf} ${account?.name||""}`.toLowerCase().includes(q)}))}
function review(){const all=state.reviewQueue||[],items=filteredReviewItems(),visible=items.slice(0,reviewFilters.limit),summary=globalThis.FINMAX_PRIVATE_REVIEW_DATA?.summary||[],sources=uniqueValues(all,reviewPdfLabel),accounts=state.accounts.filter(account=>all.some(item=>item.accountId===account.id)),types=uniqueValues(all,item=>item.suggestedType);return `${pageHead("Transaction Review","Sort by PDF, date, account, or amount so imported lines stay easy to approve.",`<button class="btn primary" data-open="transaction">Log manual item</button>`)}<div class="filter-panel review-filter-panel">${filterInput("review","query","Find",""+reviewFilters.query,"Search amount, note, category, account...")}${filterSelect("review","source","PDF",reviewFilters.source,[["all","All PDFs"],...sources.map(x=>[x,shortPdfLabel(x)])])}${filterSelect("review","account","Account",reviewFilters.account,[["all","All accounts"],...accounts.map(x=>[x.id,x.name])])}${filterSelect("review","type","Type",reviewFilters.type,[["all","All types"],...types.map(x=>[x,x])])}${filterSelect("review","sort","Sort",reviewFilters.sort,[["statement","PDF order"],["date-desc","Newest first"],["date-asc","Oldest first"],["source","Group by PDF"],["amount-desc","Highest amount"],["amount-asc","Lowest amount"]])}<button class="btn" data-filter-reset="review">Reset</button></div><div class="review-summary-bar"><strong>${all.length} pending</strong><span>${items.length} matching filters</span><span>${state.transactions.length} approved ledger entries</span>${summary.map(x=>`<span>${esc(shortPdfLabel(x.file))}: ${x.rows}</span>`).join("")}</div><div class="grid review-layout"><article class="card card-pad review-queue-card"><div class="card-head"><div><h3>Review queue</h3><span class="muted">Showing ${Math.min(visible.length,items.length)} of ${items.length}. Update expands the row into the full editor.</span></div><span class="badge ${all.length?"":"active"}">${all.length?"Needs review":"Clear"}</span></div><div class="review-list compact">${visible.map(reviewRow).join("")||`<div class="empty-review"><strong>No matching rows.</strong><p class="muted">Change the filters or reset the queue view.</p></div>`}</div>${visible.length<items.length?`<button class="btn review-more" data-review-more>Show 120 more</button>`:""}</article><aside class="grid"><article class="card card-pad"><span class="eyebrow">Rule of the app</span><h3>No imported line is trusted automatically.</h3><p class="muted">Filter by a single PDF when you want to review one statement at a time without mixing PalmPay, Moniepoint Personal, and business records.</p></article><article class="card card-pad"><h3>Fast classification</h3><div class="truth-list"><p><strong>Seen</strong><span>approve suggested meaning</span></p><p><strong>Update</strong><span>edit description, category, account, or type</span></p><p><strong>PDF order</strong><span>keeps the statement flow intact</span></p></div></article></aside></div>`}
function reviewRow(x){const account=state.accounts.find(a=>a.id===x.accountId),pdf=reviewPdfLabel(x);return `<div class="review-item"><div class="review-main"><span class="eyebrow">${esc(x.date)} · ${esc(shortPdfLabel(pdf))}</span><h3>${esc(x.name)}</h3><small>${esc(account?.name||"Unassigned")} · ${esc(x.suggestedType)} · ${esc(x.suggestedCategory)}</small></div><strong class="review-amount">${money(x.amount)}</strong><div class="review-actions"><button class="btn small" data-edit-review="${x.id}">Update</button><button class="btn small primary" data-approve-review="${x.id}">Seen</button></div></div>`}

function txSourceLabel(tx){return tx.sourceFile||tx.source||"Manual / approved"}
function sortedTransactions(items){const list=[...items],sort=txFilters.sort;if(sort==="date-asc")list.sort(compareDate);else if(sort==="amount-desc")list.sort((a,b)=>Number(b.amount||0)-Number(a.amount||0));else if(sort==="amount-asc")list.sort((a,b)=>Number(a.amount||0)-Number(b.amount||0));else if(sort==="account")list.sort((a,b)=>compareText(a,b,x=>x.account)||compareDate(b,a));else if(sort==="category")list.sort((a,b)=>compareText(a,b,x=>x.category)||compareDate(b,a));else if(sort==="type")list.sort((a,b)=>compareText(a,b,x=>x.type)||compareDate(b,a));else list.sort((a,b)=>compareDate(b,a));return list}
function filteredTransactions(){const q=txFilters.query.trim().toLowerCase();return sortedTransactions((state.transactions||[]).filter(tx=>{if(txFilters.account!=="all"&&tx.accountId!==txFilters.account)return false;if(txFilters.category!=="all"&&tx.category!==txFilters.category)return false;if(txFilters.type!=="all"&&tx.type!==txFilters.type)return false;if(txFilters.source!=="all"&&txSourceLabel(tx)!==txFilters.source)return false;if(!q)return true;return`${tx.date} ${tx.name} ${tx.rawDescription||""} ${tx.category} ${tx.account} ${tx.type} ${tx.amount} ${tx.note||""} ${txSourceLabel(tx)}`.toLowerCase().includes(q)}))}
function transactions(){const rows=filteredTransactions(),accounts=state.accounts.filter(account=>state.transactions.some(tx=>tx.accountId===account.id)),categories=uniqueValues(state.transactions,tx=>tx.category),types=uniqueValues(state.transactions,tx=>tx.type),sources=uniqueValues(state.transactions,txSourceLabel);return `${pageHead("Transactions","Approved movements with date, account, type, and category filters.",`<button class="btn primary" data-open="transaction">+ New transaction</button>`)}<div class="filter-panel tx-filter-panel">${filterInput("tx","query","Find",""+txFilters.query,"Search description, note, category...")}${filterSelect("tx","account","Account",txFilters.account,[["all","All accounts"],...accounts.map(x=>[x.id,x.name])])}${filterSelect("tx","category","Category",txFilters.category,[["all","All categories"],...categories.map(x=>[x,x])])}${filterSelect("tx","type","Type",txFilters.type,[["all","All types"],...types.map(x=>[x,x])])}${filterSelect("tx","source","Source",txFilters.source,[["all","All sources"],...sources.map(x=>[x,shortPdfLabel(x)])])}${filterSelect("tx","sort","Sort",txFilters.sort,[["date-desc","Newest first"],["date-asc","Oldest first"],["amount-desc","Highest amount"],["amount-asc","Lowest amount"],["account","Account"],["category","Category"],["type","Type"]])}<button class="btn" data-filter-reset="tx">Reset</button><button class="btn" data-action="export">Export</button></div><article class="card table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Account</th><th>Type</th><th>Source</th><th>Amount</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.date)}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.category)}</td><td>${esc(x.account)}</td><td><span class="badge ${x.type==="income"?"active":""}">${esc(x.type)}</span></td><td>${esc(shortPdfLabel(txSourceLabel(x)))}</td><td class="amount ${x.type}">${x.type==="income"?"+":x.type==="transfer"?"":"-"}${money(x.amount)}</td><td><button class="btn small danger" data-delete-tx="${x.id}">Delete</button></td></tr>`).join("")||`<tr><td colspan="8"><div class="empty-review"><strong>No matching transactions.</strong><p class="muted">Approved rows will appear here after you mark imports as Seen or log manual activity.</p></div></td></tr>`}</tbody></table></article>`}

function dashboardGoalCheckpoint(goal){const currency=goalCurrency(goal),pct=Math.min(100,Math.round((Number(goal.saved)||0)/(Number(goal.target)||1)*100)),cp=checkpointState(goal);return `<div class="dashboard-checkpoint"><div class="checkpoint-head"><div><span class="eyebrow">Active checkpoint</span><h3>${esc(goal.name)}</h3></div><strong>${pct}%</strong></div>${goalCheckpointStrip(goal,false)}<div class="checkpoint-mini-grid"><span><b>${cp.last?moneyIn(cp.last,currency,true):"None yet"}</b><small>last reached</small></span><span><b>${moneyIn(cp.next,currency,true)}</b><small>next checkpoint</small></span><span><b>${esc(goal.due)}</b><small>target date</small></span></div></div>`}
function everydayDashboard(){const t=totals(),available=sum(state.accounts,"balance"),commitments=monthlyCommitments(),reserveGap=Math.max(0,state.profile.reserveTarget-available),safe=Math.max(0,available-commitments-Math.max(0,reserveGap*.25)),spent=t.expense,budget=state.profile.monthlyBudget,pace=Math.round(spent/budget*100),goal=[...state.goals].sort((a,b)=>a.priority-b.priority)[0],advice=advisorData()[0];return `${pageHead(`Good ${greeting()}, ${esc(state.profile.name)}`,"Here is what matters most for your money today.",`<button class="btn primary" data-open="transaction">Log activity</button>`)}<article class="card safe-card"><div><span class="eyebrow">Safe to spend</span><div class="safe-value privacy-amount" data-hidden="${state.profile.privacy}">${money(safe)}</div><p>After planned commitments and reserve protection.</p></div><div class="safe-score"><strong>${Math.max(0,100-pace)}</strong><span>flexibility</span></div></article><div class="grid everyday-grid"><div class="grid"><article class="card card-pad"><div class="card-head"><div><h3>Spending pace</h3><span class="muted">${money(spent)} of ${money(budget)} monthly guardrail</span></div><strong class="${pace>85?"negative":"positive"}">${pace}%</strong></div><div class="progress pace"><span style="--value:${Math.min(100,pace)}%"></span></div><p class="muted">${pace>100?`You are ${money(spent-budget)} above your current guardrail.`:pace>80?"Slow discretionary spending to avoid crossing your limit.":`You have ${money(Math.max(0,budget-spent))} left within your current guardrail.`}</p></article><article class="card card-pad"><div class="card-head"><div><h3>Checkpoint focus</h3><span class="muted">${esc(goal?.name||"Create your first goal")}</span></div><button class="btn small" data-view="goals">Open goals</button></div>${goal?dashboardGoalCheckpoint(goal):""}</article><article class="card card-pad"><div class="card-head"><h3>Recent activity</h3><button class="btn small" data-view="transactions">View all</button></div>${state.transactions.slice(0,4).map(txRow).join("")||`<p class="muted">No approved transactions yet. Review imports first.</p>`}</article></div><aside class="grid"><article class="card advisor-preview"><span class="eyebrow">Next best move</span><h2>${advice.title}</h2><p>${advice.text}</p><button class="btn primary" data-view="advisor">See my action plan</button></article><article class="card card-pad"><div class="card-head"><h3>Coming up</h3><span class="badge">Next cycle</span></div>${upcomingRows(4)}</article><article class="card card-pad"><h3>Reserve protection</h3><div class="kpi-value">${reserveGap?money(reserveGap,true):"Ready"}</div><span class="muted">${reserveGap?"remaining to your preferred reserve":"reserve target reached"}</span></article></aside></div>`}
function rankDashboard(){const m=movementTotals(),goal=activeGoal(),reviewTotal=state.transactions.length+(state.reviewQueue||[]).length,reviewedRatio=reviewTotal?state.transactions.length/reviewTotal:1,baseAwareness=Math.min(900,reviewTotal*.42),reviewXp=state.transactions.length*5,goalXp=goal?convertMoney(Number(goal.saved)||0,goalCurrency(goal),state.profile.currency)*.002:0,xp=Math.max(0,Math.round(baseAwareness+reviewXp+(m.income*.006)+(m.protectedSavings*.01)+goalXp-(m.spending*.002))),rank=xp>8000?"A":xp>5000?"B":xp>2500?"C":xp>1000?"D":"E",next={E:1000,D:2500,C:5000,B:8000,A:12000}[rank]||12000,pct=Math.min(100,Math.round(xp/next*100)),savingRate=m.income?Math.round(m.protectedSavings/m.income*100):0;return `${pageHead(`Rank Mode, ${esc(state.profile.name)}`,"Review imports, protect savings, and turn money clarity into progress.",`<button class="btn primary" data-view="review">Open review queue</button>`)}<section class="rank-hero card"><div><span class="eyebrow">Financial Rank</span><h2>${rank} Rank</h2><p>${m.reviewCount?`${m.reviewCount} imported items still need judgement. FinMax gives some awareness XP, but the real rank jump comes from classifying them.`:"Your transaction queue is clear. Keep logging and protecting savings."}</p></div><div class="rank-orb"><strong>${rank}</strong><span>${xp} XP</span></div></section><div class="grid kpi-grid rank-kpis">${kpi("Reviewed logs",state.transactions.length,`${Math.round(reviewedRatio*100)}% of imported truth`,"positive")}${kpi("Pending review",m.reviewCount,"needs classification",m.reviewCount?"negative":"positive")}${kpi("Protected savings",m.protectedSavings,"not counted as spending","positive")}${kpi("Saving shield",`${savingRate}%`,"protected out of income",savingRate>=20?"positive":"")}</div><div class="grid dash-grid"><article class="card card-pad"><div class="card-head"><div><h3>Rank progress</h3><span class="muted">${xp} / ${next} XP toward the next bracket</span></div><span class="badge active">Balanced XP</span></div><div class="rank-track"><span style="--value:${pct}%"></span></div><div class="rank-missions"><button class="btn" data-view="review">Classify imports</button><button class="btn" data-open="transaction">Log new activity</button><button class="btn primary" data-view="goals">Push main goal</button></div></article><aside class="grid"><article class="card card-pad"><div class="card-head"><h3>Operating truth</h3><span class="badge">No shame math</span></div><div class="truth-list"><p><strong>${money(m.grossOutflow,true)}</strong><span>approved gross outflow</span></p><p><strong>${money(m.protectedSavings,true)}</strong><span>saved or protected movement</span></p><p><strong>${money(m.spending,true)}</strong><span>actual spend pressure estimate</span></p></div></article><article class="card card-pad"><h3>Primary checkpoint</h3>${goal?dashboardGoalCheckpoint(goal):`<p class="muted">Create a goal to connect Rank Mode with a target.</p>`}</article></aside></div>`}

function updateFilterControl(control){const scope=control.dataset.filterScope,key=control.dataset.filterKey,bag=scope==="review"?reviewFilters:txFilters,caret=control.selectionStart;bag[key]=control.value;if(scope==="review"&&key!=="limit")reviewFilters.limit=120;render();const next=document.querySelector(`[data-filter-scope="${scope}"][data-filter-key="${key}"]`);if(next){next.focus();if(typeof caret==="number"&&next.setSelectionRange)next.setSelectionRange(caret,caret)}}
document.addEventListener("input",e=>{const control=e.target.closest("[data-filter-scope]");if(control)updateFilterControl(control)});
document.addEventListener("change",e=>{const control=e.target.closest("[data-filter-scope]");if(control)updateFilterControl(control)});
document.addEventListener("click",e=>{if(e.target.closest("[data-review-more]")){reviewFilters.limit+=120;render();return}const reset=e.target.closest("[data-filter-reset]");if(reset){if(reset.dataset.filterReset==="review")Object.assign(reviewFilters,{query:"",source:"all",account:"all",type:"all",sort:"statement",limit:120});else Object.assign(txFilters,{query:"",account:"all",category:"all",type:"all",source:"all",sort:"date-desc"});render()}});
let pendingReviewMeta=null;
function reviewMeta(item,overrides={}){if(!item)return null;return{matchDate:overrides.date||item.date,matchAmount:Number(overrides.amount??item.amount),fields:{source:item.source||"Imported statement",sourceFile:reviewPdfLabel(item),rawDescription:statementRawDescription(item),fingerprint:item.fingerprint||item.id}}}
function applyPendingReviewMeta(){if(!pendingReviewMeta)return;const tx=state.transactions[0];if(tx?.reviewed&&tx.date===pendingReviewMeta.matchDate&&Number(tx.amount)===pendingReviewMeta.matchAmount){Object.assign(tx,pendingReviewMeta.fields);save()}pendingReviewMeta=null}
document.addEventListener("click",e=>{const btn=e.target.closest("[data-approve-review]");if(btn)pendingReviewMeta=reviewMeta(state.reviewQueue.find(x=>x.id===btn.dataset.approveReview))},{capture:true});
document.addEventListener("click",e=>{if(e.target.closest("[data-approve-review]"))applyPendingReviewMeta()});
document.addEventListener("submit",e=>{const form=e.target;if(form.dataset.form!=="review")return;const data=Object.fromEntries(new FormData(form)),item=state.reviewQueue.find(x=>x.id===data.id);pendingReviewMeta=reviewMeta(item,{date:data.date,amount:data.amount})},{capture:true});
document.addEventListener("submit",e=>{if(e.target.dataset.form==="review")applyPendingReviewMeta()});

reviewFilters.open=false;
txFilters.open=false;
let expandedIncomePathId=null;

function filterActiveCount(scope){const bag=scope==="review"?reviewFilters:txFilters,defaults=scope==="review"?{query:"",source:"all",account:"all",type:"all",sort:"statement"}:{query:"",account:"all",category:"all",type:"all",source:"all",sort:"date-desc"};return Object.entries(defaults).filter(([key,value])=>String(bag[key]??"")!==String(value)).length}
function filterDrawer(scope,fields,actions){const bag=scope==="review"?reviewFilters:txFilters,count=filterActiveCount(scope);return `<section class="filter-shell"><div class="filter-compact-row"><button class="btn filter-toggle ${bag.open?"active":""}" type="button" data-filter-toggle="${scope}" aria-expanded="${bag.open?"true":"false"}">Search and More${count?` (${count})`:""}</button><div class="filter-actions">${actions}</div></div><div class="filter-panel ${bag.open?"open":""} ${scope}-filter-panel">${fields}</div></section>`}
function resetFilterBag(scope){if(scope==="review")Object.assign(reviewFilters,{query:"",source:"all",account:"all",type:"all",sort:"statement",limit:120,open:false});else Object.assign(txFilters,{query:"",account:"all",category:"all",type:"all",source:"all",sort:"date-desc",open:false})}
function moneyGoal(value,currency){return new Intl.NumberFormat(undefined,{style:"currency",currency:currency||state.profile.currency,maximumFractionDigits:0}).format(Number(value)||0)}
function goalHoursPerDay(){const direct=Number(state.profile.goalHoursDay),weekly=Number(state.profile.goalHoursWeek);return Math.max(.25,direct||((weekly||20)/7))}
function goalPlan(goal){const paths=state.incomePaths.map(path=>({path,...pathMetrics(path,goal)})),confirmed=paths.reduce((n,x)=>n+x.soldValue,0),forecast=paths.reduce((n,x)=>n+x.plannedValue,0),hours=paths.reduce((n,x)=>n+x.hours,0),days=goalDaysLeft(goal),weeks=Math.max(1,days/7),availableHours=Math.max(1,days*goalHoursPerDay()),gap=Math.max(0,Number(goal.target)-Number(goal.saved)-confirmed),forecastGap=Math.max(0,Number(goal.target)-Number(goal.saved)-forecast);return{paths,confirmed,forecast,hours,days,weeks,availableHours,gap,forecastGap,coverage:Math.min(999,Math.round((Number(goal.saved)+forecast)/(Number(goal.target)||1)*100))}}
function goalCheckpoints(goal){const target=Number(goal.target)||0,currency=goalCurrency(goal);let points=currency==="USD"&&target>=1000000?[1000,5000,10000,25000,50000,100000,250000,500000,750000,target]:[.01,.05,.1,.25,.5,.75,1].map(p=>Math.round(target*p));return [...new Set(points.filter(x=>x>0&&x<=target))].sort((a,b)=>a-b)}
function checkpointFocus(goal){const saved=Math.max(0,Number(goal.saved)||0),points=goalCheckpoints(goal),next=points.find(x=>x>saved)||Number(goal.target)||0,last=[...points].reverse().find(x=>x<=saved)||0,pct=Math.min(100,Math.round(saved/(next||1)*100));return{saved,next,last,pct,gap:Math.max(0,next-saved)}}
function incomePathCard(path,goal){const m=pathMetrics(path,goal),currency=goalCurrency(goal),pct=m.planned?Math.min(100,Math.round(m.sold/m.planned*100)):0,capacityWarning=m.remaining>m.capacity,open=expandedIncomePathId===path.id;return `<article class="card income-path-card path-collapsed ${open?"open":""}"><div class="path-accent"></div><button class="path-summary" type="button" data-toggle-path="${path.id}"><span><small>${esc(path.status)} · ${path.currency}</small><strong>${esc(path.name)}</strong></span><span class="path-summary-price privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(path.offer,path.currency)} <small>per sale</small></span><span class="path-chevron">${open?"Hide":"Details"}</span></button>${open?`<div class="path-detail"><div class="path-stats"><div><span>Sales</span><strong>${m.sold} / ${m.planned}</strong></div><div><span>Plan value</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(m.plannedValue,currency,true)}</strong></div><div><span>Hours estimate</span><strong>${Math.round(m.hours)}h</strong></div></div><div class="progress"><span style="--value:${pct}%"></span></div>${capacityWarning?`<p class="path-warning">Planned sales exceed this path's current delivery capacity before the deadline.</p>`:`<p class="muted">About ${Math.round(m.capacity)} sales fit your stated monthly capacity.</p>`}<div class="path-actions"><button class="btn primary" data-log-path-sale="${path.id}">+ Log one sale</button><button class="btn" data-edit-path="${path.id}">Edit</button><button class="btn danger" data-delete-path="${path.id}">Remove</button></div></div>`:""}</article>`}
function review(){const all=state.reviewQueue||[],items=filteredReviewItems(),visible=items.slice(0,reviewFilters.limit),summary=globalThis.FINMAX_PRIVATE_REVIEW_DATA?.summary||[],sources=uniqueValues(all,reviewPdfLabel),accounts=state.accounts.filter(account=>all.some(item=>item.accountId===account.id)),types=uniqueValues(all,item=>item.suggestedType),fields=`${filterInput("review","query","Find",""+reviewFilters.query,"Search amount, note, category, account...")}${filterSelect("review","source","Source",reviewFilters.source,[["all","All PDFs"],...sources.map(x=>[x,shortPdfLabel(x)])])}${filterSelect("review","account","Account",reviewFilters.account,[["all","All accounts"],...accounts.map(x=>[x.id,x.name])])}${filterSelect("review","type","Type",reviewFilters.type,[["all","All types"],...types.map(x=>[x,x])])}${filterSelect("review","sort","Sort",reviewFilters.sort,[["statement","PDF order"],["date-desc","Newest first"],["date-asc","Oldest first"],["source","Group by PDF"],["amount-desc","Highest amount"],["amount-asc","Lowest amount"]])}`;return `${pageHead("Transaction Review","Sort by PDF, date, account, or amount so imported lines stay easy to approve.",`<button class="btn primary" data-open="transaction">Log manual item</button>`)}${filterDrawer("review",fields,`<button class="btn" data-filter-reset="review">Reset</button>`)}<div class="review-summary-bar"><strong>${all.length} pending</strong><span>${items.length} matching filters</span><span>${state.transactions.length} approved ledger entries</span>${summary.map(x=>`<span>${esc(shortPdfLabel(x.file))}: ${x.rows}</span>`).join("")}</div><div class="grid review-layout"><article class="card card-pad review-queue-card"><div class="card-head"><div><h3>Review queue</h3><span class="muted">Showing ${Math.min(visible.length,items.length)} of ${items.length}. Update expands the row into the full editor.</span></div><span class="badge ${all.length?"":"active"}">${all.length?"Needs review":"Clear"}</span></div><div class="review-list compact">${visible.map(reviewRow).join("")||`<div class="empty-review"><strong>No matching rows.</strong><p class="muted">Change the filters or reset the queue view.</p></div>`}</div>${visible.length<items.length?`<button class="btn review-more" data-review-more>Show 120 more</button>`:""}</article><aside class="grid"><article class="card card-pad"><span class="eyebrow">Rule of the app</span><h3>No imported line is trusted automatically.</h3><p class="muted">Filter by a single PDF when you want to review one statement at a time without mixing PalmPay, Moniepoint Personal, and business records.</p></article><article class="card card-pad"><h3>Fast classification</h3><div class="truth-list"><p><strong>Seen</strong><span>approve suggested meaning</span></p><p><strong>Update</strong><span>edit description, category, account, or type</span></p><p><strong>PDF order</strong><span>keeps the statement flow intact</span></p></div></article></aside></div>`}
function transactions(){const rows=filteredTransactions(),accounts=state.accounts.filter(account=>state.transactions.some(tx=>tx.accountId===account.id)),categories=uniqueValues(state.transactions,tx=>tx.category),types=uniqueValues(state.transactions,tx=>tx.type),sources=uniqueValues(state.transactions,txSourceLabel),fields=`${filterInput("tx","query","Find",""+txFilters.query,"Search description, note, category...")}${filterSelect("tx","account","Account",txFilters.account,[["all","All accounts"],...accounts.map(x=>[x.id,x.name])])}${filterSelect("tx","category","Category",txFilters.category,[["all","All categories"],...categories.map(x=>[x,x])])}${filterSelect("tx","type","Type",txFilters.type,[["all","All types"],...types.map(x=>[x,x])])}${filterSelect("tx","source","Source",txFilters.source,[["all","All sources"],...sources.map(x=>[x,shortPdfLabel(x)])])}${filterSelect("tx","sort","Sort",txFilters.sort,[["date-desc","Newest first"],["date-asc","Oldest first"],["amount-desc","Highest amount"],["amount-asc","Lowest amount"],["account","Account"],["category","Category"],["type","Type"]])}`;return `${pageHead("Transactions","Approved movements with date, account, type, and category filters.",`<button class="btn primary" data-open="transaction">+ New transaction</button>`)}${filterDrawer("tx",fields,`<button class="btn" data-filter-reset="tx">Reset</button><button class="btn" data-action="export">Export</button>`)}<article class="card table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Account</th><th>Type</th><th>Source</th><th>Amount</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.date)}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.category)}</td><td>${esc(x.account)}</td><td><span class="badge ${x.type==="income"?"active":""}">${esc(x.type)}</span></td><td>${esc(shortPdfLabel(txSourceLabel(x)))}</td><td class="amount ${x.type}">${x.type==="income"?"+":x.type==="transfer"?"":"-"}${money(x.amount)}</td><td><button class="btn small danger" data-delete-tx="${x.id}">Delete</button></td></tr>`).join("")||`<tr><td colspan="8"><div class="empty-review"><strong>No matching transactions.</strong><p class="muted">Approved rows will appear here after you mark imports as Seen or log manual activity.</p></div></td></tr>`}</tbody></table></article>`}
function goals(){const goal=activeGoal(),actions=`<div class="goal-page-actions"><button class="btn" data-open="incomePath">+ Income path</button><button class="btn primary" data-open="goal">+ Financial goal</button></div>`;if(!goal)return `${pageHead("Goals","Build a measurable route from today to the number that matters.",actions)}<article class="card empty-goal"><span class="eyebrow">Start here</span><h2>Create your first financial goal</h2><p>Choose a currency and deadline. FinMax will calculate the pace required without sending anything online.</p><button class="btn primary" data-open="goal">Create goal</button></article>`;const currency=goalCurrency(goal),plan=goalPlan(goal),cp=checkpointFocus(goal),other=currency==="USD"?"NGN":"USD",converted=convertMoney(goal.target,currency,other),checkpointDaily=cp.gap/Math.max(1,plan.days),capacityOver=plan.hours>plan.availableHours,covered=plan.forecastGap<=0,dailyHours=goalHoursPerDay(),workPerDay=plan.hours/Math.max(1,plan.days);return `${pageHead("Goal Lab","One target, checkpoint-first momentum, and editable income routes.",actions)}<section class="goal-command"><div class="goal-command-main"><div class="goal-command-top"><div><span class="eyebrow">Primary goal · ${esc(goal.type)} · ${currency}</span><h2>${esc(goal.name)}</h2></div><span class="goal-deadline">${plan.days} days left</span></div><div class="goal-total checkpoint-total privacy-amount" data-hidden="${state.profile.privacy}"><strong>${moneyGoal(cp.saved,currency)}</strong><span>/ ${moneyGoal(cp.next,currency)}</span></div><div class="progress goal-master-progress"><span style="--value:${cp.pct}%"></span></div><div class="goal-command-meta"><span>${cp.pct}% to next checkpoint</span><span>Full target: ${moneyIn(goal.target,currency,true)} · ${moneyIn(converted,other,true)} at your current rate</span></div></div><aside class="goal-pace"><span class="eyebrow">Checkpoint pace</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(checkpointDaily,currency,true)}</strong><span>per day</span><small>Log money when it comes in. Time capacity only estimates whether your routes still fit school.</small></aside></section><section class="goal-settings-bar"><label><span>Offline exchange rate</span><div class="inline-rate"><b>1 USD =</b><input type="number" min="1" step="1" value="${state.profile.fxUsdNgn}" data-goal-config="fxUsdNgn"><b>NGN</b></div></label><label><span>Optional focus capacity</span><div class="inline-rate"><input type="number" min=".25" max="24" step=".25" value="${Number(dailyHours.toFixed(2))}" data-goal-config="goalHoursDay"><b>hours / day</b></div></label><p>Both values stay on this device. Money logs drive progress; time just pressure-tests the plan.</p></section><div class="grid goal-kpis"><article><span>Income already won</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(plan.confirmed,currency,true)}</strong><small>From logged path sales</small></article><article><span>Planned path value</span><strong class="privacy-amount" data-hidden="${state.profile.privacy}">${moneyIn(plan.forecast,currency,true)}</strong><small>${plan.coverage}% total goal coverage</small></article><article><span>Optional time estimate</span><strong>${Number(workPerDay.toFixed(1))}h/day</strong><small>${Number(dailyHours.toFixed(1))}h/day available</small></article><article class="${covered&&!capacityOver?"plan-good":"plan-watch"}"><span>Plan signal</span><strong>${!covered?"Revenue gap":capacityOver?"Over capacity":"Covered"}</strong><small>${!covered?`${moneyIn(plan.forecastGap,currency,true)} still unassigned`:capacityOver?`${Math.round(plan.hours-plan.availableHours)}h beyond your limit`:"The route works on paper"}</small></article></div><div class="section-title goal-section-title"><div><span class="eyebrow">Income architecture</span><h2>Your routes to the goal</h2></div><span class="muted">Click a route to open details</span></div><div class="income-path-list">${state.incomePaths.map(path=>incomePathCard(path,goal)).join("")||`<article class="card empty-goal"><h3>No income paths yet</h3><p>Add the offers or products you are building.</p><button class="btn primary" data-open="incomePath">Add income path</button></article>`}</div><div class="section-title goal-section-title"><div><span class="eyebrow">Goal portfolio</span><h2>All financial goals</h2></div></div><div class="grid two-col">${[...state.goals].sort((a,b)=>(a.priority||9)-(b.priority||9)).map(g=>goalCard(g,goal)).join("")}</div>`}

document.addEventListener("click",e=>{const toggle=e.target.closest("[data-filter-toggle]");if(toggle){e.preventDefault();e.stopImmediatePropagation();const bag=toggle.dataset.filterToggle==="review"?reviewFilters:txFilters;bag.open=!bag.open;render();return}const reset=e.target.closest("[data-filter-reset]");if(reset){e.preventDefault();e.stopImmediatePropagation();resetFilterBag(reset.dataset.filterReset);render();return}const path=e.target.closest("[data-toggle-path]");if(path){e.preventDefault();e.stopImmediatePropagation();expandedIncomePathId=expandedIncomePathId===path.dataset.togglePath?null:path.dataset.togglePath;render();return}},{capture:true});
document.addEventListener("change",e=>{const config=e.target.closest('[data-goal-config="goalHoursDay"]');if(!config)return;e.stopImmediatePropagation();const value=Math.min(24,Math.max(.25,Number(config.value)||2));state.profile.goalHoursDay=value;state.profile.goalHoursWeek=value*7;config.value=value;save();render();toast("Daily focus capacity updated")},{capture:true});

function ensureUpgradeState(){state.rules=Array.isArray(state.rules)?state.rules:[];state.auditTrail=Array.isArray(state.auditTrail)?state.auditTrail:[];state.monthlyCloses=Array.isArray(state.monthlyCloses)?state.monthlyCloses:[];state.importBatches=Array.isArray(state.importBatches)?state.importBatches:[]}
ensureUpgradeState();
reviewFilters.limit=10;
txFilters.limit=10;
reviewFilters.all=false;
txFilters.all=false;

function rowPager(scope,shown,total){if(shown>=total)return `<div class="pager-row"><span>${shown} shown</span></div>`;return `<div class="pager-row"><span>${shown} of ${total} shown</span><div><button class="btn small" data-page-more="${scope}">More</button><button class="btn small" data-page-all="${scope}">All</button></div></div>`}
function resetFilterBag(scope){if(scope==="review")Object.assign(reviewFilters,{query:"",source:"all",account:"all",type:"all",sort:"statement",limit:10,all:false,open:false});else Object.assign(txFilters,{query:"",account:"all",category:"all",type:"all",source:"all",sort:"date-desc",limit:10,all:false,open:false})}
function fingerprintRow(row){return [row.date,row.amount,row.name||row.description,row.accountId||row.account,row.sourceFile||row.source].map(x=>String(x||"").trim().toLowerCase()).join("|")}
function parseImportRows(raw,accountId,source){const text=String(raw||"").trim();if(!text)return[];try{const json=JSON.parse(text);if(Array.isArray(json))return json.map((row,i)=>normalizeImportRow(row,accountId,source,i)).filter(Boolean)}catch{}const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),header=/date/i.test(lines[0])?csvCells(lines.shift()).map(x=>x.toLowerCase().trim()):["date","name","amount","type","category","note"];return lines.map((line,i)=>{const parts=csvCells(line);const row=Object.fromEntries(header.map((key,index)=>[key,parts[index]||""]));return normalizeImportRow(row,accountId,source,i)}).filter(Boolean)}
function csvCells(line){const out=[];let cell="",quoted=false;for(let i=0;i<line.length;i++){const c=line[i],next=line[i+1];if(c==='"'&&quoted&&next==='"'){cell+='"';i++;continue}if(c==='"'){quoted=!quoted;continue}if(c===","&&!quoted){out.push(cell.trim());cell="";continue}cell+=c}out.push(cell.trim());return out}
function normalizeImportRow(row,accountId,source,index=0){const amount=Number(String(row.amount||row.value||row.total||"").replace(/[^\d.-]/g,""));if(!amount)return null;const raw=row.rawDescription||row.narration||row.description||row.memo||row.name||"";return{id:row.id||uid("import"),date:row.date||new Date().toISOString().slice(0,10),name:row.name||row.description||row.memo||`Imported row ${index+1}`,rawDescription:raw,suggestedCategory:row.category||"Transfer Review",suggestedType:row.type||"transfer",accountId:row.accountId||accountId,amount:Math.abs(amount),note:row.note||`Imported through the offline wizard. Original detail: ${raw||"not provided"}`,source:source||row.source||"Manual import",sourceFile:row.sourceFile||source||row.source||"Manual import",fingerprint:row.fingerprint||""}}
function rulePattern(text){return String(text||"").toLowerCase().replace(/[^a-z0-9 ]/g," ").split(/\s+/).filter(x=>x.length>2).slice(0,4).join(" ")}
function learnRuleFromReview(item,data){const pattern=rulePattern(data.name||item?.name);if(!pattern)return;const rule={id:uid("rule"),pattern,type:data.type,category:data.category,accountId:data.accountId,createdAt:new Date().toISOString()};state.rules=state.rules.filter(x=>x.pattern!==pattern);state.rules.unshift(rule);state.rules=state.rules.slice(0,60)}
function applyReviewRules(){let count=0;(state.reviewQueue||[]).forEach(item=>{const hit=state.rules.find(rule=>rulePattern(item.name).includes(rule.pattern)||String(item.name||"").toLowerCase().includes(rule.pattern));if(hit){item.suggestedType=hit.type;item.suggestedCategory=hit.category;item.accountId=hit.accountId||item.accountId;item.note=`Rule matched: ${hit.pattern}. ${item.note||""}`.trim();count++}});save();render();toast(count?`${count} review rows updated from remembered rules`:"No matching rules yet")}
function transferMatches(limit=8){const rows=state.reviewQueue||[],matches=[];for(let i=0;i<rows.length;i++){for(let j=i+1;j<rows.length;j++){const a=rows[i],b=rows[j],sameAmount=Math.abs(Number(a.amount)-Number(b.amount))<.01,nearDate=Math.abs((Date.parse(a.date)||0)-(Date.parse(b.date)||0))<=2*86400000,differentAccount=a.accountId!==b.accountId;if(sameAmount&&nearDate&&differentAccount){matches.push([a,b]);if(matches.length>=limit)return matches}}}return matches}
function runTransferMatching(){const matches=transferMatches(40),ids=new Set(matches.flat().map(x=>x.id));(state.reviewQueue||[]).forEach(item=>{if(ids.has(item.id)){item.suggestedType="transfer";item.suggestedCategory="Transfer Review";item.note=`Potential internal transfer match found. ${item.note||""}`.trim()}});save();render();toast(matches.length?`${matches.length} likely transfer pairs marked for review`:"No likely transfer pairs found")}
function addAudit(entry){ensureUpgradeState();state.auditTrail.unshift({id:uid("audit"),at:new Date().toISOString(),...entry});state.auditTrail=state.auditTrail.slice(0,50)}
function captureUndoFromClick(target){const review=target.closest("[data-approve-review]");if(review){const item=state.reviewQueue.find(x=>x.id===review.dataset.approveReview);if(item)addAudit({kind:"review-approve",label:`Approved ${item.name}`,item:structuredClone(item)});return}const delTx=target.closest("[data-delete-tx]");if(delTx){const tx=state.transactions.find(x=>x.id===delTx.dataset.deleteTx);if(tx)addAudit({kind:"delete-tx",label:`Deleted ${tx.name}`,tx:structuredClone(tx),account:structuredClone(state.accounts.find(x=>x.id===tx.accountId))});return}const goal=target.closest("[data-contribute-goal]");if(goal){addAudit({kind:"goal-saved",label:"Goal contribution",goals:structuredClone(state.goals),accounts:structuredClone(state.accounts)});return}const logSale=target.closest("[data-log-path-sale]");if(logSale){const path=state.incomePaths.find(x=>x.id===logSale.dataset.logPathSale);if(path)addAudit({kind:"path",label:`Logged sale for ${path.name}`,path:structuredClone(path)});return}const sub=target.closest("[data-toggle-sub]");if(sub){const item=state.subscriptions.find(x=>x.id===sub.dataset.toggleSub);if(item)addAudit({kind:"sub",label:`Changed ${item.name}`,sub:structuredClone(item)});return}const removable=target.closest("[data-delete-goal],[data-delete-path],[data-delete-account]");if(removable)addAudit({kind:"collections",label:"Removed item",goals:structuredClone(state.goals),paths:structuredClone(state.incomePaths),accounts:structuredClone(state.accounts)})}
function undoLastAction(){ensureUpgradeState();const entry=state.auditTrail.shift();if(!entry)return toast("Nothing to undo yet");if(entry.kind==="review-approve"){state.transactions=state.transactions.filter(tx=>!(tx.reviewed&&tx.date===entry.item.date&&Number(tx.amount)===Number(entry.item.amount)&&tx.name===entry.item.name));if(!state.reviewQueue.some(x=>x.id===entry.item.id))state.reviewQueue.unshift(entry.item)}else if(entry.kind==="delete-tx"){state.transactions.unshift(entry.tx);const index=state.accounts.findIndex(x=>x.id===entry.account?.id);if(index>=0)state.accounts[index]=entry.account}else if(entry.kind==="goal-saved"){state.goals=entry.goals;state.accounts=entry.accounts}else if(entry.kind==="path"){const index=state.incomePaths.findIndex(x=>x.id===entry.path.id);if(index>=0)state.incomePaths[index]=entry.path}else if(entry.kind==="sub"){const index=state.subscriptions.findIndex(x=>x.id===entry.sub.id);if(index>=0)state.subscriptions[index]=entry.sub}else if(entry.kind==="collections"){state.goals=entry.goals;state.incomePaths=entry.paths;state.accounts=entry.accounts}save();render();toast(`Undone: ${entry.label}`)}
function monthKey(date=new Date()){return new Date(date).toISOString().slice(0,7)}
function monthlyCloseSummary(month=monthKey()){const rows=(state.transactions||[]).filter(tx=>String(tx.date||"").startsWith(month)),income=rows.filter(x=>x.type==="income").reduce((n,x)=>n+Number(x.amount||0),0),spending=rows.filter(x=>x.type==="expense"&&!isProtectedMovement(x)).reduce((n,x)=>n+Number(x.amount||0),0),protectedSavings=rows.filter(isProtectedMovement).reduce((n,x)=>n+Number(x.amount||0),0),subscriptions=monthlyCommitments(),loanOut=sum(state.loans,"payment"),loanIn=sum(state.loansGiven,"payment"),goal=activeGoal(),checkpoint=goal?checkpointFocus(goal):null;return{month,income,spending,protectedSavings,subscriptions,loanOut,loanIn,net:income-spending-subscriptions,checkpoint:checkpoint?{next:checkpoint.next,gap:checkpoint.gap,deadline:checkpoint.deadline}:null,createdAt:new Date().toISOString()}}
function closeMonth(){const summary=monthlyCloseSummary();state.monthlyCloses=state.monthlyCloses.filter(x=>x.month!==summary.month);state.monthlyCloses.unshift(summary);state.monthlyCloses=state.monthlyCloses.slice(0,18);save();render();toast(`${summary.month} close saved`)}
function monthlyCloseCard(){const current=monthlyCloseSummary(),last=state.monthlyCloses[0];return `<article class="card card-pad monthly-close-card"><div class="card-head"><div><span class="eyebrow">Monthly close</span><h3>${current.month}</h3></div><button class="btn small primary" data-close-month>Close month</button></div><div class="truth-list"><p><strong>${money(current.income,true)}</strong><span>approved income</span></p><p><strong>${money(current.spending,true)}</strong><span>true spending</span></p><p><strong>${money(current.protectedSavings,true)}</strong><span>protected savings movement</span></p><p><strong>${money(current.net,true)}</strong><span>net after subscriptions</span></p></div>${last?`<p class="muted">Last close saved: ${esc(last.month)}.</p>`:`<p class="muted">No closed month saved yet.</p>`}</article>`}
function goalStartDate(goal){return new Date(goal.startDate||state.profile.goalStartDate||"2026-06-25T00:00:00")}
function goalCheckpointDeadline(goal,point){const start=goalStartDate(goal),end=goalDueDate(goal),target=Number(goal.target)||1,ratio=Math.max(0,Math.min(1,Number(point||0)/target));return new Date(start.getTime()+Math.max(0,end-start)*ratio)}
function checkpointFocus(goal){const saved=Math.max(0,Number(goal.saved)||0),points=goalCheckpoints(goal),next=points.find(x=>x>saved)||Number(goal.target)||0,last=[...points].reverse().find(x=>x<=saved)||0,deadline=goalCheckpointDeadline(goal,next),days=Math.max(1,Math.ceil((deadline-new Date())/86400000)),pct=Math.min(100,Math.round(saved/(next||1)*100));return{saved,next,last,pct,gap:Math.max(0,next-saved),deadline:deadline.toISOString().slice(0,10),days,daily:Math.max(0,next-saved)/days}}
function goalCheckpointStrip(goal,full=false){const currency=goalCurrency(goal),stateCp=checkpointFocus(goal),saved=Number(goal.saved)||0,points=goalCheckpoints(goal);return `<div class="checkpoint-card ${full?"full":""}"><div class="checkpoint-copy"><span class="eyebrow">Checkpoints</span><strong>${stateCp.last?`Reached ${moneyIn(stateCp.last,currency,true)}`:"First checkpoint pending"}</strong><small>Next: ${moneyIn(stateCp.next,currency,true)} by ${esc(stateCp.deadline)}</small></div><div class="checkpoint-track" style="--checkpoint-count:${points.length}">${points.map(p=>`<span class="${saved>=p?"hit":p===stateCp.next?"next":""}" title="${moneyIn(p,currency)} by ${goalCheckpointDeadline(goal,p).toISOString().slice(0,10)}"></span>`).join("")}</div>${full?`<div class="checkpoint-labels">${points.map(p=>`<small class="${saved>=p?"hit":""}">${moneyIn(p,currency,true)} · ${goalCheckpointDeadline(goal,p).toISOString().slice(0,10)}</small>`).join("")}</div>`:""}</div>`}
function dashboardGoalCheckpoint(goal){const currency=goalCurrency(goal),cp=checkpointFocus(goal);return `<div class="dashboard-checkpoint"><div class="checkpoint-head"><div><span class="eyebrow">Active checkpoint</span><h3>${esc(goal.name)}</h3></div><strong>${cp.pct}%</strong></div>${goalCheckpointStrip(goal,false)}<div class="checkpoint-mini-grid"><span><b>${cp.last?moneyIn(cp.last,currency,true):"None yet"}</b><small>last reached</small></span><span><b>${moneyIn(cp.next,currency,true)}</b><small>next checkpoint</small></span><span><b>${cp.deadline}</b><small>checkpoint deadline</small></span></div></div>`}
function quickGoalForm(goal){return `<form class="quick-goal-form" data-form="goal-quick"><input name="goalId" value="${esc(goal.id)}" hidden><input name="delta" placeholder="+$2 or -$3" aria-label="Add or subtract goal progress"><button class="btn primary">Add</button></form>`}
function parseGoalDelta(value,currency){const raw=String(value||"").trim(),sign=raw.startsWith("-")?-1:1,amount=Number(raw.replace(/[^\d.]/g,""));return Number.isFinite(amount)?sign*amount:0}
function subscriptionForm(){const sub=state.subscriptions.find(x=>x.id===editingSubscriptionId),editing=Boolean(sub),cycle=sub?.cycle||"Monthly",next=/^\d{4}-\d{2}-\d{2}$/.test(sub?.next||"")?sub.next:new Date().toISOString().slice(0,10);return `${modalHeader(editing?"Edit subscription":"Add subscription",editing?"Correct the billing date so renewal reminders stay specific.":"Make the next recurring charge visible.")}<form data-form="subscription"><input name="id" value="${esc(sub?.id||"")}" hidden><div class="form-grid"><div class="field full"><label>Service</label><input name="name" required value="${esc(sub?.name||"")}"></div><div class="field"><label>Amount</label><input name="amount" type="number" min="0" step="0.01" required value="${sub?.amount??""}"></div><div class="field"><label>Category</label><input name="category" value="${esc(sub?.category||"Other")}"></div><div class="field"><label>Cycle</label><select name="cycle">${["Monthly","Yearly"].map(x=>`<option ${cycle===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field full"><label>Exact next billing date</label><input name="next" type="date" value="${esc(next)}"></div></div>${modalActions()}</form>`}
