function advisorData(){const t=totals(),available=sum(state.accounts,"balance"),avgExpense=state.monthly.reduce((n,x)=>n+x.expense,0)/Math.max(1,state.monthly.length),runway=available/(avgExpense||1),pace=Math.round(t.expense/state.profile.monthlyBudget*100),recurring=monthlyCommitments(),actions=[],goal=activeGoal(),cp=goal?checkpointFocus(goal):null,matches=transferMatches(10).length;if((state.reviewQueue||[]).length)actions.push({level:"urgent",title:"Clear the truth queue first",text:`You still have ${(state.reviewQueue||[]).length} imported lines waiting. Approve 10-20 at a time so the dashboard stops guessing.`,impact:"Start in Review"});if(matches)actions.push({level:"watch",title:"Mark likely internal transfers",text:`FinMax found ${matches} same-amount, nearby-date pairs across accounts. Review them before counting anything as spending.`,impact:"Reduce false spending"});if(cp)actions.push({level:cp.daily>50?"urgent":"good",title:`Reach the ${moneyIn(cp.next,goalCurrency(goal),true)} checkpoint`,text:`You need about ${moneyIn(cp.daily,goalCurrency(goal),true)} per day until ${cp.deadline}. Log confirmed income with the checkpoint Add box.`,impact:`${cp.days} days left`});if(pace>85)actions.push({level:"watch",title:"Slow discretionary spending",text:`Approved spending is at ${pace}% of your guardrail. Delay non-essential spending until income or savings context is clearer.`,impact:`Guardrail: ${money(state.profile.monthlyBudget,true)}`});if(runway<3)actions.push({level:"urgent",title:"Protect a three-month runway",text:`Liquid accounts cover about ${runway.toFixed(1)} months of average outflow. Keep savings transfers separate from spending so the runway estimate improves.`,impact:`Gap: ${money(Math.max(0,avgExpense*3-available),true)}`});if(recurring)actions.push({level:"watch",title:"Check upcoming subscriptions",text:`Recurring charges are about ${money(recurring,true)} monthly. Add exact renewal dates so you do not get surprised.`,impact:"Open Subscriptions"});const receivable=sum(state.loansGiven,"balance");if(receivable)actions.push({level:"good",title:"Follow up receivables",text:`You have ${money(receivable,true)} recorded as money owed to you. Link repayments when they arrive so cash recovery is visible.`,impact:"Loan tracker"});if(!actions.length)actions.push({level:"good",title:"Keep the system steady",text:"Your approved records are balanced. The next best move is consistent reviewing and one small goal contribution.",impact:"No urgent action"});return actions}
