function encryptedCapable(){return Boolean(globalThis.crypto?.subtle&&globalThis.TextEncoder&&globalThis.TextDecoder)}
function b64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes)))}
function ub64(value){return Uint8Array.from(atob(value),c=>c.charCodeAt(0))}
