document.addEventListener("click",e=>{captureUndoFromClick(e.target);const more=e.target.closest("[data-page-more]");if(more){e.preventDefault();e.stopImmediatePropagation();const bag=more.dataset.pageMore==="review"?reviewFilters:txFilters;bag.limit+=20;render();return}const all=e.target.closest("[data-page-all]");if(all){e.preventDefault();e.stopImmediatePropagation();const bag=all.dataset.pageAll==="review"?reviewFilters:txFilters;bag.all=true;render();return}if(e.target.closest("[data-undo-last]")){e.preventDefault();e.stopImmediatePropagation();undoLastAction();return}if(e.target.closest("[data-apply-rules]")){e.preventDefault();e.stopImmediatePropagation();applyReviewRules();return}if(e.target.closest("[data-run-transfer-match]")){e.preventDefault();e.stopImmediatePropagation();runTransferMatching();return}if(e.target.closest("[data-close-month]")){e.preventDefault();e.stopImmediatePropagation();closeMonth();return}},{capture:true});
document.addEventListener("submit",e=>{const form=e.target;if(form.dataset.form==="review"){const data=Object.fromEntries(new FormData(form)),item=state.reviewQueue.find(x=>x.id===data.id);if(item){addAudit({kind:"review-approve",label:`Updated ${item.name}`,item:structuredClone(item)});learnRuleFromReview(item,data)}}if(form.dataset.form==="goal-quick"){e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(form)),goal=state.goals.find(x=>x.id===data.goalId)||activeGoal();if(!goal)return toast("Goal not found");const delta=parseGoalDelta(data.delta,goalCurrency(goal));if(!delta)return toast("Type an amount like +$2 or -$3");addAudit({kind:"goal-saved",label:"Quick goal update",goals:structuredClone(state.goals),accounts:structuredClone(state.accounts)});goal.saved=Math.max(0,Math.min(Number(goal.target)||Infinity,(Number(goal.saved)||0)+delta));goal.updatedAt=new Date().toISOString();save();render();toast(`${delta>0?"+":""}${moneyIn(delta,goalCurrency(goal))} applied to ${goal.name}`);return}},{capture:true});
document.addEventListener("submit",async e=>{const form=e.target;if(form.dataset.form==="import-wizard"){e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(form)),rows=parseImportRows(data.rows,data.accountId,data.source),existing=new Set([...(state.reviewQueue||[]),...(state.transactions||[])].map(fingerprintRow));const fresh=rows.filter(row=>{const fp=row.fingerprint||fingerprintRow(row);row.fingerprint=fp;if(existing.has(fp))return false;existing.add(fp);return true});if(!fresh.length)return toast("No new rows found");addAudit({kind:"collections",label:"Imported review rows",goals:structuredClone(state.goals),paths:structuredClone(state.incomePaths),accounts:structuredClone(state.accounts)});state.reviewQueue.unshift(...fresh);state.importBatches.unshift({id:uid("batch"),source:data.source,count:fresh.length,createdAt:new Date().toISOString()});save();modal=null;render();toast(`${fresh.length} rows sent to Review`);return}if(form.dataset.form==="secure-backup"){e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(form));try{if(data.mode==="import"){await importSecureBackup(data.password,data.payload);modal=null;render();toast("Encrypted backup restored")}else{await exportSecureBackup(data.password);modal=null;render();toast("Encrypted backup exported")}}catch(err){toast(err.message||"Secure backup failed")}return}},{capture:true});

function startOfLocalDay(value){const d=value instanceof Date?new Date(value):new Date(value);if(Number.isNaN(d.getTime()))return new Date(new Date().setHours(0,0,0,0));d.setHours(0,0,0,0);return d}
function daysBetweenInclusive(from,to){return Math.max(1,Math.ceil((startOfLocalDay(to)-startOfLocalDay(from))/86400000)+1)}
function checkpointFocus(goal){const saved=Math.max(0,Number(goal.saved)||0),points=goalCheckpoints(goal),target=Number(goal.target)||0,today=startOfLocalDay(new Date()),unpaid=points.filter(point=>point>saved),future=unpaid.find(point=>startOfLocalDay(goalCheckpointDeadline(goal,point))>=today),next=future||unpaid[unpaid.length-1]||target,last=[...points].reverse().find(point=>point<=saved)||0,deadline=goalCheckpointDeadline(goal,next),missed=unpaid.filter(point=>startOfLocalDay(goalCheckpointDeadline(goal,point))<today&&point!==next),pct=Math.min(100,Math.round(saved/(next||1)*100)),days=daysBetweenInclusive(today,deadline);return{saved,next,last,pct,gap:Math.max(0,next-saved),deadline:deadline.toISOString().slice(0,10),days,daily:Math.max(0,next-saved)/days,missedCount:missed.length,missedTotal:missed[missed.length-1]||0,rolled:Boolean(missed.length)}}
function checkpointClass(goal,point,focus){const saved=Number(goal.saved)||0;if(saved>=point)return"hit";if(point===focus.next)return"next";return startOfLocalDay(goalCheckpointDeadline(goal,point))<startOfLocalDay(new Date())?"missed":""}
function goalCheckpointStrip(goal,full=false){const currency=goalCurrency(goal),focus=checkpointFocus(goal),points=goalCheckpoints(goal);return `<div class="checkpoint-card ${full?"full":""}"><div class="checkpoint-copy"><span class="eyebrow">Checkpoints</span><strong>${focus.rolled?`Rolled past ${focus.missedCount} missed checkpoint${focus.missedCount===1?"":"s"}`:focus.last?`Reached ${moneyIn(focus.last,currency,true)}`:"First checkpoint pending"}</strong><small>Active: ${moneyIn(focus.next,currency,true)} by ${esc(focus.deadline)}</small></div><div class="checkpoint-track" style="--checkpoint-count:${points.length}">${points.map(point=>`<span class="${checkpointClass(goal,point,focus)}" title="${moneyIn(point,currency)} by ${goalCheckpointDeadline(goal,point).toISOString().slice(0,10)}"></span>`).join("")}</div>${focus.rolled?`<p class="checkpoint-warning">Past checkpoint amounts now fold into this active checkpoint so the plan keeps moving cleanly.</p>`:""}${full?`<div class="checkpoint-labels">${points.map(point=>`<small class="${checkpointClass(goal,point,focus)}">${moneyIn(point,currency,true)} - ${goalCheckpointDeadline(goal,point).toISOString().slice(0,10)}</small>`).join("")}</div>`:""}</div>`}
function dashboardGoalCheckpoint(goal){const currency=goalCurrency(goal),cp=checkpointFocus(goal);return `<div class="dashboard-checkpoint"><div class="checkpoint-head"><div><span class="eyebrow">Checkpoint focus</span><h3>${moneyIn(cp.saved,currency,true)} / ${moneyIn(cp.next,currency,true)}</h3><small class="muted">${esc(goal.name)}</small></div><strong>${cp.pct}%</strong></div>${goalCheckpointStrip(goal,false)}<div class="checkpoint-mini-grid"><span><b>${cp.last?moneyIn(cp.last,currency,true):"None yet"}</b><small>last reached</small></span><span><b>${moneyIn(cp.gap,currency,true)}</b><small>remaining now</small></span><span><b>${cp.deadline}</b><small>checkpoint deadline</small></span></div></div>`}

const builtInReviewRules=[
  {label:"Cross-account transfer",type:"transfer",category:"Transfer Review",keywords:["transfer","trf","sent","received","balance","wallet funding"],note:"Likely money moved between your own accounts. Confirm both sides before approval."},
  {label:"Savings movement",type:"transfer",category:"Savings",keywords:["cashbox","spend & save","spend and save","savings","save","smart earn","piggy","stash","vault"],note:"Likely savings or reserve movement, so it should not count as spending unless you confirm otherwise."},
  {label:"Loan or repayment",type:"loan-given",category:"Loan",keywords:["loan","borrow","debt","repayment","repaid","gemini"],note:"Likely loan activity. Confirm whether you gave money out or received repayment."},
  {label:"Data or airtime",type:"expense",category:"Data/Airtime",keywords:["data","airtime","mtn","airtel","glo","9mobile","bundle","recharge"],note:"Likely phone data, airtime, or internet spending."},
  {label:"Subscription",type:"expense",category:"Subscription",keywords:["subscription","chatgpt","canva","netflix","spotify","google","icloud","domain","hosting"],note:"Likely recurring software, media, or service cost."},
  {label:"Bank fees",type:"expense",category:"Fees",keywords:["fee","fees","charge","charges","stamp duty","vat","levy","commission"],note:"Likely bank or platform fee."},
  {label:"Cash/POS withdrawal",type:"transfer",category:"Transfer Review",keywords:["pos","withdrawal","cash withdrawal","agent"],note:"Likely cash withdrawal. Mark the final purpose only if you know what the cash was used for."},
  {label:"Income signal",type:"income",category:"Income",keywords:["cashback","interest","reward","commission received","payment received","income"],note:"Likely income, refund, interest, or reward. Confirm before approving."}
];
function reviewText(item){return `${item.name||""} ${statementRawDescription(item)} ${item.note||""} ${item.suggestedCategory||""} ${item.source||""} ${statementSourceFile(item)}`.toLowerCase()}
function builtInGuess(item){const text=reviewText(item);return builtInReviewRules.find(rule=>rule.keywords.some(keyword=>text.includes(keyword)))}
function applyGuessToItem(item,guess,reason){if(!item||!guess)return false;const before=`${item.suggestedType}|${item.suggestedCategory}|${item.accountId||""}|${item.note||""}`;item.suggestedType=guess.type;item.suggestedCategory=guess.category;if(guess.accountId)item.accountId=guess.accountId;const prefix=`${reason}: ${guess.label}.`;item.note=String(item.note||"").includes(prefix)?item.note:`${prefix} ${guess.note} ${item.note||""}`.trim();return before!==`${item.suggestedType}|${item.suggestedCategory}|${item.accountId||""}|${item.note||""}`}
function applyReviewRules(){let count=0;(state.reviewQueue||[]).forEach(item=>{const learned=state.rules.find(rule=>rulePattern(item.name).includes(rule.pattern)||String(item.name||"").toLowerCase().includes(rule.pattern));if(learned&&applyGuessToItem(item,{label:`Remembered rule "${learned.pattern}"`,type:learned.type,category:learned.category,accountId:learned.accountId,note:"This came from a previous update you made."},"Learned rule"))count++;const guess=builtInGuess(item);if(guess&&applyGuessToItem(item,guess,"Suggested"))count++});save();render();toast(count?`${count} review rows auto-sorted for your approval`:"No matching review rules yet")}
function runTransferMatching(){const matches=transferMatches(60),ids=new Set(matches.flat().map(item=>item.id));let count=0;(state.reviewQueue||[]).forEach(item=>{if(ids.has(item.id)&&applyGuessToItem(item,{label:"Likely internal transfer pair",type:"transfer",category:"Transfer Review",note:"Same amount appears close together in another account. Confirm before approving."},"Transfer match"))count++});save();render();toast(count?`${count} possible cross-account transfer rows marked`:"No likely transfer pairs found")}
function ruleCards(){const learned=(state.rules||[]).slice(0,4),built=builtInReviewRules.slice(0,6);return `<article class="card card-pad rules-card"><div class="card-head"><div><span class="eyebrow">Rules</span><h3>Review sorting rules</h3></div><span class="badge ${learned.length?"active":""}">${learned.length} learned</span></div><div class="rule-list">${built.map(rule=>`<span><strong>${esc(rule.label)}</strong><small>${esc(rule.category)}</small></span>`).join("")}</div>${learned.length?`<div class="learned-rules">${learned.map(rule=>`<small>${esc(rule.pattern)} -> ${esc(rule.type)} / ${esc(rule.category)}</small>`).join("")}</div>`:`<p class="muted compact-note">No learned rules yet. Update one row and FinMax will remember the pattern locally.</p>`}<div class="sub-actions"><button class="btn small primary" data-apply-rules>Auto-sort guesses</button><button class="btn small" data-run-transfer-match>Find transfers</button></div></article>`}
function sourceSummaryButton(row){const label=shortPdfLabel(row.file),active=reviewFilters.source===row.file;return `<button class="summary-chip ${active?"active":""}" type="button" data-review-source="${esc(row.file)}" title="Filter Review to ${esc(row.file)}">${esc(label)}: ${row.rows}</button>`}
function review(){const all=state.reviewQueue||[],items=filteredReviewItems(),visible=reviewFilters.all?items:items.slice(0,reviewFilters.limit),summary=globalThis.FINMAX_PRIVATE_REVIEW_DATA?.summary||[],sources=uniqueValues(all,reviewPdfLabel),accounts=state.accounts.filter(account=>all.some(item=>item.accountId===account.id)),types=uniqueValues(all,item=>item.suggestedType),matches=transferMatches(3),fields=`${filterInput("review","query","Find",""+reviewFilters.query,"Search amount, note, category, account...")}${filterSelect("review","source","Source",reviewFilters.source,[["all","All PDFs"],...sources.map(x=>[x,shortPdfLabel(x)])])}${filterSelect("review","account","Account",reviewFilters.account,[["all","All accounts"],...accounts.map(x=>[x.id,x.name])])}${filterSelect("review","type","Type",reviewFilters.type,[["all","All types"],...types.map(x=>[x,x])])}${filterSelect("review","sort","Sort",reviewFilters.sort,[["statement","PDF order"],["date-desc","Newest first"],["date-asc","Oldest first"],["source","Group by PDF"],["amount-desc","Highest amount"],["amount-asc","Lowest amount"]])}`;return `${pageHead("Transaction Review","Import, sort, approve, and teach FinMax what each line means.",`<button class="btn" data-open="importWizard">Import wizard</button><button class="btn primary" data-open="transaction">Log manual item</button>`)}${filterDrawer("review",fields,`<button class="btn" data-filter-reset="review">Reset</button>`)}<div class="review-summary-bar"><button class="summary-chip strong" type="button" data-review-source="all">${all.length} pending</button><span>${items.length} matching filters</span><button class="summary-chip" type="button" data-view="transactions">${state.transactions.length} approved ledger entries</button>${summary.map(sourceSummaryButton).join("")}</div><div class="grid review-layout"><article class="card card-pad review-queue-card"><div class="card-head"><div><h3>Review queue</h3><span class="muted">Showing ${Math.min(visible.length,items.length)} of ${items.length}. More keeps the page light.</span></div><span class="badge ${all.length?"":"active"}">${all.length?"Needs review":"Clear"}</span></div><div class="review-list compact">${visible.map(reviewRow).join("")||`<div class="empty-review"><strong>No matching rows.</strong><p class="muted">Change the filters or reset the queue view.</p></div>`}</div>${rowPager("review",visible.length,items.length)}</article><aside class="grid review-side-panel">${ruleCards()}<article class="card card-pad"><span class="eyebrow">Cross-account transfers</span><h3>${matches.length} likely pairs</h3><p class="muted">${matches.length?"Same amount, nearby date, different account. Mark them as neutral transfer candidates before approval.":"No obvious transfer pairs in the current filtered sample."}</p></article><article class="card card-pad audit-card"><h3>Audit trail</h3><p class="muted">${state.auditTrail.length} reversible actions saved locally.</p><button class="btn" data-undo-last>Undo last action</button></article></aside></div>`}
document.addEventListener("click",e=>{const source=e.target.closest("[data-review-source]");if(!source)return;e.preventDefault();e.stopImmediatePropagation();reviewFilters.source=source.dataset.reviewSource||"all";reviewFilters.limit=10;reviewFilters.all=false;reviewFilters.open=false;render()},{capture:true});

