let finmaxGoalPortfolioOpen=false;
let finmaxUmbrellaDraft={};
const reviewSmartBuckets=[
  ["all","All"],
  ["savings","Savings"],
  ["cross","Cross-accounts"],
  ["loan","Loan"],
  ["pos","POS for cash"],
  ["data","Data"],
  ["airtime","Airtime"],
  ["fees","Bank fees"],
  ["subs","Subscriptions"],
  ["interest","Interest"],
  ["unsure","Unsure yet"]
];
