function txIntelligence(tx){
  const text=`${tx.name} ${tx.category} ${tx.note||""}`.toLowerCase();
  if(tx.type==="transfer"||/transfer|sent|received|wallet/.test(text))return"Transfer movement";
  if(/save|savings|cashbox|smartearn|piggy/.test(text))return"Protected savings";
  if(/loan|borrow|repay/.test(text))return"Loan activity";
  if(/data|airtime|bundle|recharge/.test(text))return"Phone/data";
  if(/subscription|chatgpt|canva|netflix|spotify/.test(text))return"Subscription";
  if(/fee|charge|vat|stamp/.test(text))return"Bank fee";
  return tx.type==="income"?"Income":"Spending";
}
function txCard(tx){
  const account=state.accounts.find(a=>a.id===tx.accountId);
  const raw=tx.rawDescription||"";
  return `<details class="tx-card"><summary><div><span class="eyebrow">${esc(tx.date)} - ${esc(accountShortName(account))}</span><h3>${esc(tx.name)}</h3><small>${esc(raw||txIntelligence(tx))}</small></div><strong class="amount ${tx.type}">${tx.type==="income"?"+":tx.type==="transfer"?"":"-"}${money(tx.amount)}</strong><span class="review-open">Open</span></summary><div class="tx-detail"><div class="detail-grid"><span><b>Category</b><small>${esc(tx.category)}</small></span><span><b>Account</b><small>${esc(tx.account||account?.name||"Account")}</small></span><span><b>Type</b><small>${esc(tx.type)}</small></span><span><b>Source</b><small>${esc(smartSourceName(txSourceLabel(tx)))}</small></span>${raw?`<span><b>Original narration</b><small>${esc(raw)}</small></span>`:""}</div>${tx.note?`<p>${esc(tx.note)}</p>`:""}<button class="btn small danger" data-delete-tx="${tx.id}">Delete</button></div></details>`;
}
