function defaultPackageFor(path){return{id:"pkg_default",name:"Standard",price:Number(path.offer)||0,hours:Number(path.hoursPerSale)||0}}
function packageList(path){const list=Array.isArray(path.packages)&&path.packages.length?path.packages:[defaultPackageFor(path)];return list.map((pkg,i)=>({id:pkg.id||`pkg_${i}`,name:String(pkg.name||`Package ${i+1}`),price:Number(pkg.price)||0,hours:Number(pkg.hours)||Number(path.hoursPerSale)||0}))}
function packageLines(path){return packageList(path).map(pkg=>`${pkg.name} | ${pkg.price} | ${pkg.hours}`).join("\n")}
function parsePackageLines(raw,path){const rows=String(raw||"").split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map((line,i)=>{const [name,price,hours]=line.split("|").map(x=>x?.trim());return{id:`pkg_${Date.now()}_${i}`,name:name||`Package ${i+1}`,price:Number(price)||Number(path.offer)||0,hours:Number(hours)||Number(path.hoursPerSale)||0}});return rows.length?rows:[defaultPackageFor(path)]}
function pathMetrics(path,goal){
  const currency=goalCurrency(goal),packages=packageList(path),avgPrice=packages.reduce((n,x)=>n+x.price,0)/Math.max(1,packages.length),avgHours=packages.reduce((n,x)=>n+x.hours,0)/Math.max(1,packages.length),salesLog=Array.isArray(path.salesLog)?path.salesLog:[],sold=salesLog.length||Math.max(0,Number(path.sold)||0),planned=Math.max(sold,Number(path.plannedSales)||0),legacySold=salesLog.length?0:sold*(Number(path.offer)||avgPrice),loggedValue=salesLog.reduce((n,x)=>n+Number(x.price||0),legacySold),remaining=Math.max(0,planned-sold),soldValue=convertMoney(loggedValue,path.currency,currency),plannedValue=convertMoney(planned*avgPrice,path.currency,currency),hours=remaining*avgHours,capacity=Math.max(0,Number(path.monthlyCapacity)||0)*Math.max(1,goalDaysLeft(goal)/30.44);
  return{sold,planned,remaining,soldValue,plannedValue,hours,capacity,avgPrice,avgHours};
}
function goalPlan(goal){const paths=state.incomePaths.map(path=>({path,...pathMetrics(path,goal)})),confirmed=paths.reduce((n,x)=>n+x.soldValue,0),forecast=paths.reduce((n,x)=>n+x.plannedValue,0),hours=paths.reduce((n,x)=>n+x.hours,0),days=goalDaysLeft(goal),weeks=Math.max(1,days/7),availableHours=weeks*Math.max(1,Number(state.profile.goalHoursWeek)||20),gap=Math.max(0,Number(goal.target)-Number(goal.saved)-confirmed),forecastGap=Math.max(0,Number(goal.target)-Number(goal.saved)-forecast);return{paths,confirmed,forecast,hours,days,weeks,availableHours,gap,forecastGap,coverage:Math.min(999,Math.round((Number(goal.saved)+forecast)/(Number(goal.target)||1)*100))}}
