function accountUmbrella(account){
  if(account?.umbrella)return account.umbrella;
  const text=`${account.name} ${account.kind} ${account.type} ${account.institution}`.toLowerCase();
  if(text.includes("piggyvest")||text.includes("stock")||text.includes("invest")||text.includes("bamboo")||text.includes("rise"))return"Investment";
  if(text.includes("cashbox")||text.includes("smartearn")||text.includes("spend & save")||text.includes("spend and save"))return"Savings";
  if(account.kind==="Business"||text.includes("business"))return"Business";
  if(text.includes("cash"))return"Cash";
  return account.kind==="Personal"?"Personal":"Needs sorting";
}
function umbrellaOptions(current){return["Personal","Business","Savings","Investment","Cash","Needs sorting"].map(x=>`<option ${current===x?"selected":""}>${x}</option>`).join("")}
function umbrellaCard(account){
  const current=finmaxUmbrellaDraft?.[account.id]||accountUmbrella(account);
  return `<article class="umbrella-account"><div><span class="eyebrow">${esc(accountShortName(account))}</span><strong>${esc(account.name)}</strong><small class="privacy-amount" data-hidden="${state.profile.privacy}">${money(account.balance)}</small></div><select data-account-umbrella="${account.id}">${umbrellaOptions(current)}</select></article>`;
}
