  const groups=["Personal","Business","Savings","Investment","Cash","Needs sorting"].map(label=>({label,items:state.accounts.filter(account=>(finmaxUmbrellaDraft?.[account.id]||accountUmbrella(account))===label)}));
  return `${pageHead("Accounts","Sort accounts into umbrellas so personal, business, savings, investments, and cash never blur together.",`<button class="btn primary" data-open="account">+ Add account</button>`)}<div class="grid kpi-grid">${kpi("All account balances",sum(state.accounts,"balance"),`${state.accounts.length} offline accounts`)}${kpi("Personal",sum(state.accounts.filter(x=>accountUmbrella(x)==="Personal"),"balance"),"daily money")}${kpi("Business",sum(state.accounts.filter(x=>accountUmbrella(x)==="Business"),"balance"),"work money")}${kpi("Protected",sum(state.accounts.filter(x=>["Savings","Investment"].includes(accountUmbrella(x))),"balance"),"savings + investments")}</div><article class="card card-pad umbrella-lab"><div class="card-head"><div><span class="eyebrow">Umbrella lab</span><h3>Drag with your decisions, then save.</h3><p class="muted">Use the dropdown beside each account to decide where it belongs. FinMax remembers the umbrella after you save.</p></div><button class="btn primary" data-save-umbrellas>Save umbrellas</button></div><div class="umbrella-grid">${groups.map(group=>`<details class="umbrella-group" ${group.items.length?"open":""}><summary><span>${esc(group.label)}</span><strong>${money(sum(group.items,"balance"))}</strong><small>${group.items.length} accounts</small></summary><div>${group.items.map(umbrellaCard).join("")||`<p class="muted">Nothing here yet.</p>`}</div></details>`).join("")}</div></article>`;
