document.addEventListener("submit",e=>{
  const form=e.target;
  if(form.dataset.form==="income-path-advanced"){
    e.preventDefault();e.stopImmediatePropagation();
    const data=Object.fromEntries(new FormData(form)),payload={id:data.id||uid("path"),name:data.name.trim(),currency:data.currency,offer:Number(data.offer),plannedSales:Number(data.plannedSales),sold:Number(data.sold),hoursPerSale:Number(data.hoursPerSale),monthlyCapacity:Number(data.monthlyCapacity),status:data.status,salesLog:[],packages:[]};
    const existing=state.incomePaths.find(x=>x.id===payload.id);
    payload.salesLog=Array.isArray(existing?.salesLog)?existing.salesLog:[];
    payload.packages=parsePackageLines(data.packages,payload);
    if(payload.sold>payload.plannedSales)return toast("Sales already won cannot exceed planned sales");
    const index=state.incomePaths.findIndex(x=>x.id===payload.id);
    if(index>=0)state.incomePaths[index]=payload;else state.incomePaths.push(payload);
    editingPathId=null;modal=null;save();render();toast("Income path packages saved");return;
  }
  if(form.dataset.form==="path-sale"){
    e.preventDefault();e.stopImmediatePropagation();
    const data=Object.fromEntries(new FormData(form)),path=state.incomePaths.find(x=>x.id===data.pathId);
    if(!path)return toast("Income path not found");
    const pkg=packageList(path).find(x=>x.id===data.packageId)||packageList(path)[0],units=Math.max(1,Number(data.units)||1);
    path.salesLog=Array.isArray(path.salesLog)?path.salesLog:[];
    for(let i=0;i<units;i++)path.salesLog.unshift({id:uid("sale"),packageId:pkg.id,packageName:pkg.name,price:pkg.price,hours:pkg.hours,date:data.date,description:data.description||pkg.name});
    path.sold=Math.max(Number(path.sold)||0,path.salesLog.length);
    path.plannedSales=Math.max(Number(path.plannedSales)||0,path.sold);
    modal=null;save();render();toast(`${units} ${pkg.name} sale${units===1?"":"s"} logged`);return;
  }
},{capture:true});

