  account.balance=Number(account.balance||0)+amount;
  state.transactions.unshift({id:uid("tx"),date:new Date().toISOString().slice(0,10),name:`Invoice paid - ${invoice.title}`,category:"Income",account:account.name,accountId:account.id,type:"income",amount,note:`Business invoice from ${clientNameForInvoice(invoice)} marked paid.`});
